const CURATED_6STAGE_SYLLABI = {"心理学":{"stages":[{"name":"入门筑基与心理研究方法","goal":"建立科学的心理学视角与可证伪研究思维，摆脱日常伪心理直觉","topics":[{"title":"心理学导论：研究对象、主要流派与学科性质","intro":"心理学是研究心理现象及其发生发展规律的科学，兼具自然科学与社会科学双重属性。","textbook":"《普通心理学》（彭聃龄，北京师范大学出版社）"},{"title":"科学心理学研究方法：实验设计、相关研究与伦理规范","intro":"实验法通过操纵自变量与控制无关变量来检验因果关系，相关研究则评估变量共变方向与强度。","textbook":"《心理学研究方法》（舒华，人民教育出版社）"},{"title":"心理统计核心逻辑：描述统计、假设检验与效应量","intro":"用均值与标准差概括数据分布，再借显著性检验（p 值）与效应量判断差异是否具有统计学意义与实际价值。","textbook":"《现代心理与教育统计学》（张厚粲、徐建平）"},{"title":"心理测量原理：信度、效度与标准化量表编制","intro":"信度反映测量结果的一致性与稳定性，效度决定量表是否真正测到目标心理特质。","textbook":"《心理与教育测量》（戴海琦，暨南大学出版社）"}]},{"name":"生理机制、感知觉与意识基础","goal":"从神经递质与大脑加工通路出发，理解心理活动如何产生","topics":[{"title":"行为神经科学基础：神经元、突触传递与脑区功能定位","intro":"神经元通过动作电位传导与突触化学递质实现信息编码，皮层各叶协作支撑语言、记忆与决策。","textbook":"《生理心理学》（沈政、林庶芝，北京大学出版社）"},{"title":"感觉加工：绝对阈限、差别阈限与韦伯-费希纳定律","intro":"感觉是对客观刺激个别属性的直接反映，感受性受韦伯比例常数调控而非简单线性叠加。","textbook":"《心理学与生活》（格里格、津巴多，人民邮电出版社）"},{"title":"知觉组织规律：格式塔原则、深度线索与自上而下加工","intro":"知觉主动把零散感觉刺激整合成整体意义，经验预期与当前刺激共同塑造成像与识别结果。","textbook":"《认知心理学》（王甦、汪安圣，北京大学出版社）"},{"title":"注意、睡眠节律与意识状态的神经调控","intro":"选择性注意如同信息瓶颈过滤器分配认知资源，昼夜节律与快波睡眠共同维系情绪整理与记忆巩固。","textbook":"《意识的科学探索》（Baars & Gage）"}]},{"name":"学习机制、记忆编码与认知决策","goal":"拆解人类获取知识、形成习惯与做出理性/偏差判断的底层模型","topics":[{"title":"行为主义学习律：经典条件反射与操作性强化程序","intro":"巴甫洛夫配对联结与斯金纳强化-惩罚机制揭示环境后果如何塑造习惯、恐惧与回避行为。","textbook":"《学习心理学》（Domjan，中国轻工业出版社）"},{"title":"多重记忆系统：感觉记忆、工作记忆与长时提取线索","intro":"信息依次经历编码、保持与提取；工作记忆容量受限，提取成效取决于编码特异性与干扰强度。","textbook":"《记忆心理学》（Baddeley，中国人民大学出版社）"},{"title":"思维、问题解决与启发式认知偏差（Kahneman 双系统）","intro":"快系统1依赖直觉启发式高效运行却易落入可得性与锚定偏差，慢系统2负责谨慎逻辑复核。","textbook":"《思考，快与慢》（Daniel Kahneman）"},{"title":"语言习得与表征：语音、句法树与心理词典激活","intro":"儿童在先天普遍语法与社会交互中快速掌握语言，语义网络以激活扩散形式支撑实时理解。","textbook":"《心理语言学》（桂诗春，外语教学与研究出版社）"}]},{"name":"动机情绪、发展轨迹与人格结构","goal":"理解驱动个体行动的能量来源与毕生心理成长规律","topics":[{"title":"动机与目标驱动：自我决定理论、归因风格与内在兴趣","intro":"自主感、胜任感与关系感三大心理需求滋养持久内驱力，把成败归因于可控努力更能维持韧性。","textbook":"《动机心理学》（Deckers，机械工业出版社）"},{"title":"情绪加工与调节策略：沙赫特两因素理论与认知重评","intro":"情绪是生理唤醒与情境认知评估交互的产物，事前认知重评比事后表达抑制更利于心理健康。","textbook":"《情绪心理学》（Strongman，中国轻工业出版社）"},{"title":"毕生发展心理学：依恋类型、皮亚杰阶段与青少年同一性","intro":"早期安全依恋构建内工作模式，认知发展从具体运算走向形式抽象并完成自我同一性整合。","textbook":"《发展心理学》（林崇德，人民教育出版社）"},{"title":"人格科学：大五人格特质模型与遗传-环境交互作用","intro":"开放性、尽责性、外向性、宜人性与神经质五个稳定维度刻画个体在长期情境中的行为倾向。","textbook":"《人格心理学》（Burger，中国轻工业出版社）"}]},{"name":"社会互动与异常心理评估","goal":"识别群体压力对个体的隐蔽塑形，建立规范的心理困扰识别框架","topics":[{"title":"社会认知：基本归因错误、刻板印象与认知失调改变","intro":"人们评价他人时低估环境推力而高估性格因素；观念与行为冲突时的失调感促使自我合理化。","textbook":"《社会心理学》（侯玉波，北京大学出版社）"},{"title":"群体动力学：阿希从众、米尔格拉姆服从与旁观者效应","intro":"群体规范压力与责任分散显著改写个人决策阈值，看清情境力量有助于守住独立理性边界。","textbook":"《社会性动物》（Elliot Aronson）"},{"title":"变态心理学导论：生物-心理-社会模型与 DSM/ICD 诊断框架","intro":"判断心理异常需综合考量统计学偏离、主观痛苦感与社会功能受损，坚持多维成因整合观。","textbook":"《变态心理学》（钱铭怡，北京大学出版社）"},{"title":"常见情绪与压力障碍：抑郁发作、焦虑谱系与创伤应激机制","intro":"抑郁核心表现为持续心境低落与兴趣丧失，焦虑则以过度预期威胁及自主神经过度激活为特征。","textbook":"《精神病学》（郝伟、陆林，人民卫生出版社）"}]},{"name":"心理咨询技术与循证干预实践","goal":"贯通咨询伦理与主流循证疗法，形成自助助人的专业实操框架","topics":[{"title":"咨询关系与伦理底线：保密原则、双重关系回避与知情同意","intro":"安全共情、无条件积极关注与严格边界保密是有效心理工作的前提，遇自伤危机须立即启动破密救护。","textbook":"《心理咨询与心理治疗》（钱铭怡，北京大学出版社）"},{"title":"认知行为疗法（CBT）实务：识别自动化负性思维与行为激活","intro":"通过思维记录表检验灾难化信念并设计小步行为实验，在现实反馈中打破抑郁焦虑维持环路。","textbook":"《认知行为疗法：基础与应用》（Judith Beck）"},{"title":"人本主义与正念接纳技术（ACT/MBCT）实操框架","intro":"不与痛苦念头强行对抗，而是以去融合视角接纳当下情绪并按核心价值采取承诺行动。","textbook":"《正念与接纳承诺疗法实操》"},{"title":"应用心理学前沿：积极心理干预与科研/科普素养实战","intro":"运用感恩记录、优势发挥与科学证据检索区分市面上良莠不齐的心理建议，独立完成主题调研。","textbook":"《积极心理学》（Seligman）"}]}]},"法学":{"stages":[{"name":"法理学基石与法律解释方法","goal":"建立法科生核心价值尺度和法律文本推理规范","topics":[{"title":"法理学导论：法律特征、渊源效力位阶与法律关系","intro":"法律以国家强制力为后盾，遵循上位法优于下位法、特别法优于一般法、新法优于旧法规则。","textbook":"《法理学》（张文显主编，高等教育出版社）"},{"title":"法律规范结构、法律责任与归责原则体系","intro":"完整法律规范由假定条件、行为模式与法律后果构成；明确区分过错责任、无过错责任与公平分担。","textbook":"《法理学初阶》（付子堂，法律出版社）"},{"title":"法律解释方法位阶：文义解释、体系解释、目的解释与漏洞填补","intro":"面对法条歧义时先作字面文义界定，再结合条文前后体系与立法目的综合衡平判断。","textbook":"《法学方法论》（齐佩利乌斯，法律出版社）"},{"title":"法律职业伦理与司法推理三段论实战训练","intro":"训练大前提（法律规范）、小前提（案件事实）与判决结论之间严格一致的函摄推理能力。","textbook":"《法律思维》（林来梵）"}]},{"name":"宪法、国家治理与行政法治","goal":"掌握公法控权原理与公民基本权利救济路径","topics":[{"title":"宪法基本原理：人民主权、基本权利效力与违宪审查理念","intro":"宪法是国家根本法，核心功能在于规范公权力边界并切实保障公民平等权、言论与人身自由。","textbook":"《宪法学》（韩大元主编，高等教育出版社）"},{"title":"国家机构体系与央地立法权限划分","intro":"理清全国人大、国务院、监察委员会及人民法院与人民检察院的宪法定位与监督制衡机制。","textbook":"《中国宪法教程》（胡锦光）"},{"title":"行政法三大原则：依法行政、比例原则与正当程序","intro":"行政机关不仅不得越权，还须采用对公民权益损害最小的妥当手段并保障陈述申辩权。","textbook":"《行政法与行政诉讼法》（姜明安主编，北京大学出版社）"},{"title":"具体行政行为、行政复议与行政诉讼举证责任倒置","intro":"行政诉讼由被告行政机关负主要举证责任证明行为合法，凸显公法监督制约本质。","textbook":"《行政法学》（章剑生）"}]},{"name":"民法典总则、物权与债权核心","goal":"理清平等主体间人身财产流转规则与违约/侵权定责","topics":[{"title":"民法典总则：民事主体、意思表示与法律行为效力","intro":"以意思自治为核心，精准辨析有效、无效、可撤销与效力待定法律行为的界限及诉讼时效规则。","textbook":"《民法学》（王利明主编，中国人民大学出版社）"},{"title":"物权法体系：所有权、占有保护、善意取得与担保物权","intro":"掌握不动产登记生效、动产交付公示及抵押/质押/留置三大担保优先受偿次序与物权请求权。","textbook":"《物权法》（崔建远，中国人民大学出版社）"},{"title":"合同编核心：要约承诺、履行抗辩与违约损害赔偿","intro":"穿透同时履行、先履行与不安抗辩权适用要件，学会计算违约金调整、定金罚则与可得利益。","textbook":"《合同法学》（韩世远，法律出版社）"},{"title":"侵权责任编：过错归责、无过错类型与因果关系认定","intro":"结合高空抛物、医疗损害及网络侵权条款，拆解过错要件与多因一果中的责任比例划分。","textbook":"《侵权责任法》（程啸，法律出版社）"}]},{"name":"刑法犯罪构成与刑罚裁量体系","goal":"建立罪刑法定底线与阶层式定罪分析习惯","topics":[{"title":"刑法三大原则与阶层式犯罪构成判断路径","intro":"坚持罪刑法定、罪刑相适应与平等适用；沿「构成要件符合性→违法性→有责性」顺序理性审查入罪。","textbook":"《刑法学》（张明楷，法律出版社）"},{"title":"故意与过失、因果关系判断及正当防卫边界","intro":"界分间接故意与过于自信过失，掌握不法侵害进行时下正当防卫与防卫过当的法益衡量。","textbook":"《刑法学》（周光权，中国人民大学出版社）"},{"title":"故意犯罪形态、共同犯罪与罪数竞合规则","intro":"梳理预备、未遂、中止的量刑差异，精准处理共同正犯、帮助犯与想象竞合从一重处断难题。","textbook":"《刑法各论核心专题》（陈兴良）"},{"title":"重点罪名精析：财产犯罪、人身法益保护与经济秩序罪","intro":"分辨盗窃与诈骗的处分意识分界，把握侵占、抢劫转化及非法集资类罪名的定罪要点。","textbook":"《刑法重点案例精讲》"}]},{"name":"民刑诉讼程序与证据规则实务","goal":"看懂庭审攻防节奏、管辖定位与举证质证准则","topics":[{"title":"民事诉讼程序：管辖确定、诉讼标的与谁主张谁举证","intro":"区分级别管辖与地域管辖防踩坑，运用要件事实证明责任分配决定胜负走向。","textbook":"《民事诉讼法》（张卫平，法律出版社）"},{"title":"刑事诉讼程序与人权保障：非法证据排除规则","intro":"理解侦查、起诉与审判分工配合，掌握刑讯逼供等非法言词证据绝对排除的法定程序。","textbook":"《刑事诉讼法》（陈瑞华，北京大学出版社）"},{"title":"商法基础脉络：公司法人人格否认与股东出资责任","intro":"穿透有限公司有限责任原则与公司僵局救济，厘清高管忠实勤勉义务与认缴制加速到期边界。","textbook":"《公司法学》（赵旭东，高等教育出版社）"},{"title":"知识产权核心：著作权、专利权与商标权权利边界","intro":"把握独创性、新颖性与显著性核心标准，辨析合理使用与商业维权常见争议类型。","textbook":"《知识产权法》（王迁，中国人民大学出版社）"}]},{"name":"法条检索、文书写作与法律诊所实战","goal":"从记忆法条升级为独立完成类案检索与专业法律意见","topics":[{"title":"规范化法律检索：指导性案例检索与裁判规则提炼","intro":"学会在权威法规库与裁判文书中提炼争议焦点、法条援引链与同案不同判风险点。","textbook":"《法律检索实务指南》"},{"title":"法律文书撰写：起诉状、答辩状与合同风控审查清单","intro":"用清晰事实脉络与请求权基础规范草拟起诉意见，并学会识别常见商事合同高危陷阱条款。","textbook":"《法律文书写作教程》"},{"title":"劳动与消费者维权专题：双倍工资、竞业限制与格式条款","intro":"将实体法融入职场试用期纠纷、加班举证与网络消费七日无理由退货等高频生活场景。","textbook":"《劳动合同法实务解析》"},{"title":"模拟法庭与疑难请求权基础综合案例全真推演","intro":"针对一宗跨越民刑交叉的复杂事实，逐一梳理各请求权基础并撰写书面法律分析报告。","textbook":"《请求权基础案例研习》（朱晓喆）"}]}]},"汉语言文学":{"stages":[{"name":"语言文字基石与汉语结构规律","goal":"打通语音、文字、词汇与语法的汉语本体分析能力","topics":[{"title":"现代汉语语音系统：声韵调规律与音变现象","intro":"掌握汉语普通话音节结构与轻声、儿化、上声变调规则，建立规范音系视角。","textbook":"《现代汉语》（黄伯荣、廖序东主编，高等教育出版社）"},{"title":"现代汉语词汇与语法分析：语素、短语与复句层次","intro":"用直接成分层次分析法拆解歧义短语与多重复句，分辨虚词在语境中的精确语法义。","textbook":"《现代汉语语法讲义》（朱德熙，商务印书馆）"},{"title":"古代汉语与工具书检索：六书造字法与词类活用","intro":"借助说文解字与古籍注疏把握象形会意形声逻辑，精准识别使动、意动与宾语前置句式。","textbook":"《古代汉语》（王力主编，中华书局）"},{"title":"语言学纲要：符号任意性、音系学与语义演变类型","intro":"理解能指与所指的任意性约定关系，看懂古今词义扩大、缩小与感情色彩转移的轨迹。","textbook":"《语言学纲要》（叶蜚声、徐通锵，北京大学出版社）"}]},{"name":"先秦两汉至魏晋南北朝文学源流","goal":"梳理中国文学史前期经典文本谱系与美学精神觉醒","topics":[{"title":"诗经风雅颂、赋比兴与楚辞浪漫主义源头","intro":"对比北方现实主义四言传统与屈原香草美人抒情体系，把握中国古典诗歌双璧格局。","textbook":"《中国文学史》（袁行霈主编，高等教育出版社）"},{"title":"先秦诸子散文与《左传》《战国策》叙事传统","intro":"赏析孟庄论辩艺术与先秦史传散文如何通过细节对话勾勒人物精神风骨。","textbook":"《中国古代文学史》（马积高、黄钧）"},{"title":"《史记》纪传体美学与汉乐府诗叙事传统","intro":"剖析司马迁互见法如何写就「史家之绝唱」，兼观汉代民间乐府诗对社会疾苦的直写。","textbook":"《中国文学史讲义》（程千帆）"},{"title":"建安风骨、陶渊明田园诗与魏晋文学自觉时代","intro":"理解魏晋文人从「文以载道」走向个体生命忧患与审美独立的时代转折。","textbook":"《魏晋文学与思想》（刘跃进）"}]},{"name":"唐宋文学高峰与明清小说戏曲","goal":"深入诗词格律、唐宋古文运动与市井章回叙事高峰","topics":[{"title":"盛唐气象与格律诗美学：李白豪放与杜甫沉郁顿挫","intro":"学会切分近体律诗平仄黏对，并在时代盛衰对照中精读李杜诗作的章法炼字技巧。","textbook":"《唐诗鉴赏辞典》与《诗词格律》（王力）"},{"title":"宋词雅俗流变与唐宋八大家古文散体革新","intro":"梳理苏辛豪放派与柳周婉约派词体差异，看懂韩愈欧阳修以文为道兼重章法气韵。","textbook":"《唐宋词史论》（王兆鹏）"},{"title":"元杂剧舞台结构与明清四大奇书叙事演进","intro":"把握关汉卿、汤显祖戏剧冲突构造，梳理《三国》《水浒》《西游》《红楼》视角嬗变。","textbook":"《中国小说史略》（鲁迅）"},{"title":"《红楼梦》草蛇灰线叙事学与晚清文学转型启蒙","intro":"运用细读法剖析大观园人物镜像关系及晚清白话小说对现代报刊叙事的催生。","textbook":"《红楼梦研究》（俞平伯/周汝昌）"}]},{"name":"现当代中国文学思潮与作家文本细读","goal":"理解百年现代性经验如何塑造中国新文学经典","topics":[{"title":"五四文学革命与鲁迅《呐喊》《彷徨》国民性批判","intro":"深入鲁迅冷峻叙事视角与反讽结构，剖析现代知识分子启蒙困境与精神解剖深度。","textbook":"《中国现代文学三十年》（钱理群等，北京大学出版社）"},{"title":"三十年代多元流派：茅盾、巴金、老舍与沈从文乡土书写","intro":"比较都市社会剖析小说、市民风俗书写与湘西诗意田园之间的审美张力与历史寄托。","textbook":"《中国现代小说史》（夏志清）"},{"title":"新时期文学流派演进：寻根、先锋实验与余华/莫言叙事","intro":"看懂当代小说如何在语言形式革新、历史魔幻叙事与民间现实主义之间拓展表现力。","textbook":"《中国当代文学史》（洪子诚，北京大学出版社）"},{"title":"现当代诗歌与散文经典细读：新诗意象与自由韵律","intro":"对比闻一多三美主张与海子/北岛现代意象密度，体悟现代汉语书面语的审美节律。","textbook":"《现代汉诗导论》"}]},{"name":"外国文学谱系与文艺学核心范畴","goal":"建立跨文化文学视野，学会运用文学理论切入文本批评","topics":[{"title":"古希腊史诗悲剧与文艺复兴人文主义奠基","intro":"精读荷马史诗英雄观与莎士比亚戏剧人性悲剧内核，理解西方文学源头命题。","textbook":"《外国文学史》（郑克鲁主编，高等教育出版社）"},{"title":"十九世纪现实主义与现代主义意识流小说革命","intro":"跨越巴尔扎克、托尔斯泰社会全景画卷与卡夫卡、乔伊斯心理时间重构的叙事边界。","textbook":"《小说面面观》（E.M.福斯特）"},{"title":"文学理论五大核心：文本细读、叙事学与接受美学","intro":"利用叙事聚焦、隐含作者与召唤结构理论解释同一部作品为何在不同年代衍生新解。","textbook":"《文学理论教程》（童庆炳主编，高等教育出版社）"},{"title":"西方文论方法入门：形式主义陌生化、原型批评与结构主义","intro":"学会识别「陌生化」「二元对立」与原型母题，避免评论文章停留在泛泛读后感。","textbook":"《二十世纪西方文学理论》（特里·伊格尔顿）"}]},{"name":"创意写作、文献考据与学术论文实务","goal":"把阅读鉴赏转化为扎实的学术论文写作与创意文本产出","topics":[{"title":"学术文献检索与目录学基础：四库提要与当代数据库","intro":"运用古籍数字化检索平台与核心期刊目录高效定位版本异文与既有学术综述。","textbook":"《中国古典文献学》（吴枫）"},{"title":"文本细读与文学评论写作：问题意识确立与论证闭环","intro":"学会从文本微小裂隙提出真问题，围绕一线原始引文展开有理有据的学理推演。","textbook":"《文本细读方法论》（南帆）"},{"title":"创意写作与非虚构叙事：视角调度、留白与人物弧光","intro":"练习通过感官细节与克制对话推进情节，而非用干瘪心理形容词替读者下结论。","textbook":"《小说写作的艺术》"},{"title":"学位论文规范与综合答辩模拟：综述、摘要与引注规范","intro":"按国家规范完成文献综述、摘要提炼、注释体例校验与答辩PPT问题拆解。","textbook":"《中文学科论文写作指南》"}]}]},"临床医学":{"stages":[{"name":"正常人体解剖与生理机能基础","goal":"搭建精确的人体器官空间地图与生命稳态调节框架","topics":[{"title":"系统解剖学导论：运动系统、心血管路径与内脏毗邻定位","intro":"掌握人体标准解剖学姿势、关节运动轴面与大/小循环血管解剖走行及重要器官体表投影。","textbook":"《系统解剖学》（丁文龙、王海杰，人民卫生出版社）"},{"title":"组织胚胎学概览：四大基本组织与早期胚胎三胚层发育","intro":"区分上皮、结缔、肌组织与神经组织的镜下结构，理解器官畸形发生与胚胎发育关键窗口期。","textbook":"《组织学与胚胎学》（李继承）"},{"title":"细胞生理与稳态调控：跨膜转运、动作电位与内环境稳态","intro":"理解钠钾泵、电压门控通道如何触发动作电位，以及负反馈机制维持血压血糖稳态。","textbook":"《生理学》（王庭槐主编，人民卫生出版社）"},{"title":"医学免疫学基石：固有免疫应答与适应性T/B细胞协同","intro":"厘清抗原呈递、抗体分类功能（IgG/IgM等）及免疫耐受失衡引发超敏/自免疾病的逻辑。","textbook":"《医学免疫学》（曹雪涛主编，人民卫生出版社）"}]},{"name":"生物化学、病原生物与病理损伤","goal":"读懂代谢通路故障、感染致病与组织病变微观本质","topics":[{"title":"医学生物化学：糖脂代谢核心通路与酶学调控节点","intro":"串联糖酵解、三羧酸循环与氧化磷酸化能量产率，看懂酮症酸中毒等临床代谢紊乱成因。","textbook":"《生物化学与分子生物学》（周春燕）"},{"title":"医学微生物与寄生虫学：细菌毒素、病毒复制与院感防控","intro":"按革兰染色、衣壳包膜特征分类常见病原体，理解耐药机制与无菌操作消毒灭菌标准。","textbook":"《医学微生物学》（李凡主编）"},{"title":"总论病理学：细胞适应与坏死凋亡、炎症渗出与血栓形成","intro":"识别肥大化生与干湿性坏疽镜下差异，追溯炎症血管反应与血栓脱落引发梗死的过程。","textbook":"《病理学》（步宏、李一雷，人民卫生出版社）"},{"title":"肿瘤病理与病理生理学：良恶性分化差异与酸碱水电失衡","intro":"对比良恶性肿瘤生长方式及转移路径，学会根据血气指标初步判别代酸、呼碱与休克分期。","textbook":"《病理生理学》（王建枝）"}]},{"name":"诊断学、药理学与临床基本技能","goal":"完成从基础课到病房床旁的衔接，学会问诊查体与安全选药","topics":[{"title":"临床症状学与规范化问诊技巧：胸痛、发热、呼吸困难鉴别","intro":"按诱因、部位、性质、持续时间与伴随症状追问关键线索，防漏急危重致命病因。","textbook":"《诊断学》（万学红主编，人民卫生出版社）"},{"title":"系统体格检查与心电图读片基础：心肺听诊与 ST-T 识别","intro":"规范运用视触叩听采集阳性体征，掌握正常十二导联心电图及心肌缺血/心律失常入门识别。","textbook":"《体格检查与心电图精解》"},{"title":"医学影像与临床检验判读：血常规、肝肾功与胸部 CT 基础","intro":"通过白细胞分类区分细菌/病毒感染倾向，结合炎症因子与影像肺纹理变化辅助诊断。","textbook":"《医学影像学》（徐克）"},{"title":"临床药理学总论：药动学半衰期、量效关系与抗菌药物分级","intro":"理解表观分布容积与稳态血药浓度原理，严守抗菌药物合理使用边界与常见不良反应监测。","textbook":"《药理学》（杨宝峰主编，人民卫生出版社）"}]},{"name":"内科学核心系统疾病诊疗思维","goal":"围绕呼吸循环消化内分泌四大重点专科构建鉴别诊断树","topics":[{"title":"循环系统：高血压分级管理、冠心病急性胸痛与心衰救治","intro":"熟练识别急性冠脉综合征黄金救治窗，掌握降压五类一线药物与心衰强心利尿扩管策略。","textbook":"《内科学》（葛均波、徐永健，人民卫生出版社）"},{"title":"呼吸系统：慢阻肺、社区获得性肺炎与肺栓塞危重筛查","intro":"结合肺功能 FEV1/FVC 标准诊治慢阻肺，掌握低氧呼衰 I/II 型吸氧浓度规范设置。","textbook":"《呼吸内科学经典病例解析》"},{"title":"消化系统：消化性溃疡出血、肝硬化失代偿与急性胰腺炎","intro":"理解消化道出血止血抑酸时机、肝硬化门脉高压并发症处理与重症胰腺炎早期液体复苏。","textbook":"《内科学》（消化分册）"},{"title":"内分泌与泌尿核心：糖尿病分型诊治与急慢性肾损伤评估","intro":"区别1/2型糖尿病与酮症酸中毒胰岛素泵入原则，学会按 eGFR 与尿蛋白评估肾功。","textbook":"《实用内科学》"}]},{"name":"外科学急症、妇儿及全科急救处理","goal":"建立外科无菌与手术适应证观念，掌握院前/急诊致命急症处置","topics":[{"title":"外科学总论与急腹症鉴别：阑尾炎、肠梗阻与消化道穿孔","intro":"恪守严格无菌术原则与围手术期水电平衡，学会鉴别疼痛性质以决定保守或手术探查。","textbook":"《外科学》（陈孝平、汪建平，人民卫生出版社）"},{"title":"骨创伤、颅脑损伤与烧伤休克早期评估处置","intro":"识别硬膜外血肿中间清醒期、开放性骨折清创止血优先级与烧伤面积补液公式应用。","textbook":"《骨科与急诊创伤临床指南》"},{"title":"妇产与儿科关键指征：高危妊娠预警与儿童高热惊厥/脱水","intro":"重点牢记妊娠期高血压、产后出血急救流程及儿童补液张力计算与呼吸道梗阻识别。","textbook":"《妇产科学》与《儿科学》（人民卫生出版社）"},{"title":"心肺脑复苏（BLS/ALS）与急性中毒/过敏性休克规范流程","intro":"按高质量胸外按压 C-A-B 节奏演练院内院外抢救，掌握肾上腺素首选用药与气道开放技术。","textbook":"《急诊与灾难医学》（于学忠）"}]},{"name":"循证医学、医患沟通与临床决策实战","goal":"将医疗人文关怀与循证指南整合为严谨安全的全周期诊治能力","topics":[{"title":"循证医学实战：PICO 检索、Meta 分析森林图与指南证据等级","intro":"学会读懂临床指南推荐级别与异质性指标，避免仅凭个别经验病例做出超适应证决策。","textbook":"《循证医学》（李幼平，高等教育出版社）"},{"title":"医患沟通艺术与坏消息告知原则（SPIKES 框架）","intro":"尊重患者知情选择权与心理承受节奏，共情澄清治疗预后与潜在手术并发症。","textbook":"《医患沟通技能教程》"},{"title":"临床思维防误区：锚定偏差、过早闭合与多学科 MDT 协作","intro":"系统复盘误诊漏诊经典教训，利用检验前概率与鉴别诊断清单防止「只见一叶」。","textbook":"《临床思维与误诊防范》"},{"title":"全流程综合模拟病例（OSCE 多站演练）与执业安全守则","intro":"贯穿接诊问病史、查体开单、病历书写与危重处理四环节，检验临床综合胜任力。","textbook":"《中国临床医师执业能力指南》"}]}]},"新闻传播":{"stages":[{"name":"新闻传播学核心理论与媒介演进","goal":"掌握受众、媒介与社会舆论运作的底层解释框架","topics":[{"title":"新闻学概论：新闻真实性、新闻价值五要素与党性人民性","intro":"理解时新性、重要性、显著性、接近性与趣味性如何筛选事实，坚守事实核查生命线。","textbook":"《新闻学概论》（李良荣，复旦大学出版社）"},{"title":"传播学五大模式演进：香农-韦弗线性模式到互动媒介观","intro":"看清噪声与反馈如何改写信息抵达率，跨越传统单向「魔弹论」认知误区。","textbook":"《传播学教程》（郭庆光，中国人民大学出版社）"},{"title":"舆论场经典理论：议程设置、沉默的螺旋与培养理论","intro":"剖析大众媒体如何决定「公众讨论什么」，以及社交从众压力怎样压缩少数观点发声空间。","textbook":"《大众传播理论：范式与流派》（刘海龙）"},{"title":"媒介技术史：口语、印刷术、电子广播与算法智能分发","intro":"沿着麦克卢汉「媒介即讯息」视角，追踪不同媒介形态对公共领域与记忆方式的塑形。","textbook":"《理解媒介》（马歇尔·麦克卢汉）"}]},{"name":"新闻采写、事实核查与深度报道","goal":"养成专业记者的采访敏感度、消息源核实与多体裁成稿功力","topics":[{"title":"新闻采访筹备、提问策略与敏感场景突破","intro":"区分封闭式核实提问与开放式追问技巧，掌握交叉访谈多方信源防偏信的原则。","textbook":"《新闻采访教程》（张征，中国人民大学出版社）"},{"title":"新闻消息倒金字塔结构与多维特稿叙事架构","intro":"练就导语一句抓出核心新闻眼的硬功，同时掌握非虚构特稿的人物场景白描技巧。","textbook":"《新闻写作教程》（刘明华）"},{"title":"深度调查记者核查工具链：公开检索、信源三角互证与辟谣","intro":"学会利用工商企查、裁判文书与图像元数据反转检索鉴别假新闻与断章取义内容。","textbook":"《深度报道方法与实战》"},{"title":"新闻编辑标题艺术、版面视觉层级与融媒体编排","intro":"在严守「标题不过度惊悚失实」前提下提炼动作感与张力感，提升阅读首屏停驻率。","textbook":"《新闻编辑学》（蔡雯，中国人民大学出版社）"}]},{"name":"数字新闻、数据可视化与智能媒体","goal":"从传统采写升级为数据驱动、交互表达与流媒体产品构建","topics":[{"title":"数据新闻制作流：数据清洗、指标构建与统计陷阱甄别","intro":"看透平均数误导与相关性偷换因果，利用结构化数据讲出扎实可验证的公共议题。","textbook":"《数据新闻概论与实操》"},{"title":"新媒体图文排版、交互图表叙事与信息图设计原理","intro":"控制视觉焦点与数据墨水比，让复杂趋势折线与对比关系在移动端一秒看清。","textbook":"《信息可视化设计实战》"},{"title":"短视频与视听语言：分镜景别、声音设计及前 3 秒钩子","intro":"把握特写/全景叙事节奏、同期声还原与竖屏构图法则，平衡信息密度与观感流畅。","textbook":"《视听新闻与数字视频创作》"},{"title":"算法推荐原理与信息茧房治理：协同过滤与平台分发机制","intro":"剖析点击率与完播率权重如何放大情绪回音壁，探索负责任的公共议题破圈路径。","textbook":"《算法新闻与智能传播》"}]},{"name":"广告创意、品牌传播与公共关系","goal":"掌握整合营销传播（IMC）模型与危机公关实战应急方案","topics":[{"title":"整合营销传播（IMC）与受众洞察：用户旅程全触点规划","intro":"从痛点动机挖掘用户真实需求，串联认知、兴趣、行动与复购阶段的差异化信息策略。","textbook":"《广告学概论》（陈培爱）"},{"title":"品牌定位与文案创意方法：USP 提炼与共情故事结构","intro":"明确产品差异化唯一卖点，通过视觉隐喻与场景痛点文案建立长期品牌心智资产。","textbook":"《定位》（艾·里斯、杰克·特劳特）"},{"title":"公共关系实务与舆情监测：声誉管理与议题沟通","intro":"学会建立企业日常利益相关者沟通池，在潜在不满萌芽阶段通过透明对话消除误解。","textbook":"《公共关系学》（胡百精，中国人民大学出版社）"},{"title":"危机公关黄金 4 小时处置与事实声明撰写实训","intro":"遵循「态度诚恳、事实明确、行动具体」三原则处理舆论危机，警惕自辩式推责激化矛盾。","textbook":"《危机传播管理》（胡百精）"}]},{"name":"传播研究方法与受众量化洞察","goal":"用社会科学实证手段测算传播效果，避免仅靠灵感做策划","topics":[{"title":"量化研究方法：问卷设计原则、抽样偏差控制与信效度检验","intro":"防范引导性题干与幸存者偏差，利用概率抽样与统计显著性科学评估受众态度变化。","textbook":"《传播研究方法》（巴比/柯惠新）"},{"title":"内容分析法与话语分析：编码类目表制定及隐含框架解读","intro":"对媒体样本系统抽样并由双编码员一致性检验，量化揭示报道偏向或价值倾向。","textbook":"《媒介研究方法》"},{"title":"A/B 测试与新媒体运营漏斗：点击、留存与转化归因","intro":"学会读懂公众号打开率、完读跳出曲线及私域转发系数，持续迭代内容运营决策。","textbook":"《新媒体数据分析与运营实战》"},{"title":"传媒法规与新闻伦理红线：名誉权、隐私权、肖像权与著作权","intro":"区分合法舆论监督批评与侵权诽谤边界，规范未成年人打码与合理引用转载标示。","textbook":"《新闻传播法教程》（魏永征）"}]},{"name":"跨媒体全案策划与毕业级作品实战","goal":"综合采编、数据视觉、传播策略完成经得起市场考验的媒体产品","topics":[{"title":"全媒体专题策划书写作：选题论证、渠道矩阵与排期表","intro":"依据目标人群习惯选配长文深度+图表卡+短视频切条分发链路并预设量化 KPI。","textbook":"《融媒体报道策划实务》"},{"title":"AI 辅助采编规范：提示词工程与大模型幻觉人工复核","intro":"将大模型用于资料整理、大纲拓展与多平台改写，但对事实人名、引文与数字坚持零信任人工核验。","textbook":"《生成式AI与新闻实务规范》"},{"title":"国际传播与跨文化叙事策略：高语境与低语境沟通避坑","intro":"避免口号化自说自话，学习用国际受众听得懂的个体故事与普适共情语言讲述真实发展。","textbook":"《跨文化传播学》（孙英春）"},{"title":"综合融媒体作品闭环汇报与传播效果复盘答辩","intro":"独立交付包含采写文稿、可视化组件与运营转化数据复盘表的完整作品集。","textbook":"《全媒体融合毕业实战指引》"}]}]},"经济学":{"stages":[{"name":"经济学思维基石与微观供需均衡","goal":"学会用机会成本、边际分析与均衡视角解释市场价格运行","topics":[{"title":"经济学核心思维：稀缺性、机会成本与边际分析法则","intro":"资源稀缺决定凡选择皆有代价；理性决策看的是未来增加一单位行动的边际收益与边际成本。","textbook":"《经济学原理：微观分册》（曼昆，北京大学出版社）"},{"title":"供给与需求曲线：价格发现机制、弹性与税收归宿分析","intro":"供需弹性比例决定税收或涨价负担主要由买方还是卖方承担，并非名义征税对象承担全部。","textbook":"《微观经济学》（平狄克，中国人民大学出版社）"},{"title":"消费者选择理论：效用无差异曲线、预算线与替代/收入效应","intro":"商品降价既让人多买相对便宜货（替代效应），也 equivalent 提升实际购买力（收入效应）。","textbook":"《微观经济学：现代观点》（范里安）"},{"title":"比较优势与自由贸易原理：机会成本差异如何创造双赢剩余","intro":"即使一方各项生产率皆占绝对优势，聚焦各自机会成本最低的专业分工仍能做大总产出。","textbook":"《国际经济学》（保罗·克鲁格曼）"}]},{"name":"市场结构、博弈论与市场失灵修正","goal":"理解企业定价策略、垄断成因与公共物品/外部性治理","topics":[{"title":"生产成本结构与完全竞争企业定价决策（MC = MR 准则）","intro":"区分沉没成本与可变成本，明白短期内只要价格高于平均可变成本企业就不应立即停产。","textbook":"《中级微观经济学》"},{"title":"垄断、垄断竞争与寡头定价：三级价格歧视与双边平台","intro":"企业借助会员分级、学生票与早鸟票识别不同需求弹性群体，将部分消费者剩余转为利润。","textbook":"《产业组织理论》（梯若尔）"},{"title":"博弈论入门：占优策略、囚徒困境与纳什均衡实景剖析","intro":"个人理性往往通往集体非理性均衡，看清重复博弈与可置信承诺如何改写价格战困局。","textbook":"《策略思维》（迪克西特、奈尔伯夫）"},{"title":"市场失灵与政府干预：外部性、搭便车与信息不对称","intro":"针对污染负外部性、公共品及逆向选择与道德风险，分别采用庇古税、产权界定与信号传递化解。","textbook":"《制度与公共经济学》"}]},{"name":"宏观经济国民核算与长期增长引擎","goal":"学会看懂 GDP、CPI、失业率等宏观核心仪表盘与增长源泉","topics":[{"title":"国民收入核算三大路径：支出法 GDP、实际名义区分与通胀衡量","intro":"看清消费、投资、政府购买与净出口结构，用 GDP 平减指数和 CPI 剔除物价虚高。","textbook":"《宏观经济学》（曼昆，中国人民大学出版社）"},{"title":"失业类型与菲利普斯曲线权衡：自然失业率与通胀预期","intro":"分辨结构性失业、周期性失业与摩擦性失业，理解短期通胀降失业何以长期回归自然率。","textbook":"《宏观经济学》（布兰查德）"},{"title":"索洛增长模型核心洞察：储蓄率、技术进步与全要素生产率","intro":"单纯堆砌资本投资受报酬递减限制必然触及稳态，唯有技术创新与人力资本驱动长期繁荣。","textbook":"《经济增长》（巴罗）"},{"title":"宏观收入分配与共同富裕指标：基尼系数、要素分配与人力资本","intro":"用洛伦兹曲线与基尼系数评估初次及再分配格局，均衡效率激励与社会保障兜底机制。","textbook":"《发展经济学》（张培刚）"}]},{"name":"货币银行、财政金融与总需求周期","goal":"贯通央行印钞乘数、利率传导与财政赤字的逆周期调节工具","topics":[{"title":"货币创造机制：基础货币、法定准备金与商业银行信贷乘数","intro":"商业银行通过吸储放贷成倍扩张广义货币 M2，流动性既决定交易便利也牵动资产估值。","textbook":"《货币金融学》（米什金，中国人民大学出版社）"},{"title":"IS-LM 模型与宏观政策协同：财政扩张挤出效应与流动性陷阱","intro":"分析积极财政发债与稳健货币降息在刺激内需时如何配合发力并避免挤出民间投资。","textbook":"《现代宏观经济学分析》"},{"title":"汇率决定与国际收支：购买力平价、利率平价与不可能三角","intro":"理解一国货币难以同时兼顾固定汇率、资本自由流动与货币政策独立性三项目标。","textbook":"《国际金融学》（姜波克，复旦大学出版社）"},{"title":"金融危机与资产泡沫防范：明斯基时刻与宏微观审慎监管","intro":"追踪从谨慎融资走向庞氏融资的杠杆周期，识别银行挤兑传染链与央行最后贷款人角色。","textbook":"《金融危机与宏观审慎》"}]},{"name":"政治经济学、计量工具与因果推断实战","goal":"告别拍脑袋归因，学会使用计量回归区分相关性与真实因果","topics":[{"title":"政治经济学经典逻辑：劳动价值论、剩余价值与当代市场转型","intro":"贯通古典与马克思主义商品二重性理论，深入理解中国社会主义市场经济制度优势。","textbook":"《马克思主义政治经济学概论》（高等教育出版社）"},{"title":"计量经济学入门：最小二乘法 OLS、遗漏变量偏误与多重共线性","intro":"直观理解回归系数控制变量的意义，避免将同受第三因素影响的两组数误作因果。","textbook":"《计量经济学导论》（伍德里奇，中国人民大学出版社）"},{"title":"现代因果推断利器：随机对照实验 RCT、双重差分 DID 与工具变量","intro":"用政策试点自然实验的平行趋势对照剥离政策真实净效应，是当代实证论文必考利器。","textbook":"《基本无害的计量经济学》（安格里斯特）"},{"title":"公开经济数据查询与指标拆解：统计年鉴、PMI 与社融解读","intro":"追踪制造业 PMI 荣枯线与社会融资规模结构，将新闻快讯转为有数可查的经济研判。","textbook":"《中国宏观经济数据实战手册》"}]},{"name":"前沿公共政策分析与商业经济应用","goal":"将理论工具落地于平台经济、碳中和、产业转型与投资决策","topics":[{"title":"平台经济学与双边市场：网络效应、交叉补贴与反垄断规制","intro":"拆解外卖、网约车平台如何利用双边正向网络效应构建护城河及算法定价合谋隐患。","textbook":"《平台革命》与数字经济专题"},{"title":"行为经济学精要：前景理论损失厌恶、心理账户与助推 Nudge","intro":"揭示损失带来的痛感往往两倍于等量所得，学会巧用默认选项助推养老储蓄与健康习惯。","textbook":"《错误的行为》（理查德·泰勒）"},{"title":"能源转型与绿色经济：碳交易定价、ESG 与外部性内部化路径","intro":"比较碳税与碳排放权总量配额交易机制如何引导企业以最低边际减排成本完成绿色升级。","textbook":"《环境与自然资源经济学》"},{"title":"经济学综合行业研报实训：从数据采集到政策/企业策略建议","intro":"选取某一具体消费或新兴行业，完成从供需格局、计量/财务论证到策略结论的完整研报。","textbook":"《经管研报与政策评估方法》"}]}]},"金融学":{"stages":[{"name":"货币时间价值与金融市场架构","goal":"建立现值贴现直觉，认清各大金融市场与金融机构运行规则","topics":[{"title":"货币时间价值：复利、净现值 NPV 与内部收益率 IRR 算账法","intro":"明白今天的 1 元比明天更值钱，一切估值本质上都是未来预期现金流按风险折现到今天的总和。","textbook":"《公司理财》（罗斯，机械工业出版社）"},{"title":"利率本质、收益率曲线形态与通胀调整（费雪效应）","intro":"会看长短期国债利差倒挂预警信号，并学会把名义利率刨除预期通胀还原成实际回报。","textbook":"《货币金融学》（米什金）"},{"title":"直接融资 vs 间接融资：股票、债券、银行与影子银行体系","intro":"理解股票、债券与信贷各自的风险承接机制，分清募资方信用等级与流动性差异。","textbook":"《金融学》（黄达，中国人民大学出版社）"},{"title":"财务报表三张表透视：资产负债、利润及自由现金流 FCF","intro":"跳出账面利润幻觉，通过经营现金流与应收/存货周转识别真赚钱与虚胖型企业。","textbook":"《财务报表分析与证券估值》（佩因曼）"}]},{"name":"资产定价基石与投资组合管理","goal":"学会量化度量风险与收益权衡，告别情绪化孤注一掷","topics":[{"title":"马科维茨均值-方差组合理论：分散化如何消除非系统性风险","intro":"相关性低于 1 的资产组合可以在不压低预期收益的同时显著降低总体波动率，做到唯一免费午餐。","textbook":"《投资学》（滋维·博迪，机械工业出版社）"},{"title":"资本资产定价模型 CAPM：β 系数、系统风险溢价与 α 追求","intro":"明白大盘波动 beta 驱动市场常规回报，而真正超额收益 alpha 源于稀缺定价偏差或价值增长。","textbook":"《现代投资组合理论与投资分析》"},{"title":"有效市场假说 EMH 与行为金融学套利限制剖析","intro":"辩证评估信息吸收速度与羊群效应、处置效应带来的非理性错误定价机会与时间代价。","textbook":"《非理性繁荣》（罗伯特·席勒）"},{"title":"多因子量化模型概览：规模、价值、动量与质量因子","intro":"认识 Fama-French 多因子框架如何拆分基金超额绩效，分辨运气暴发还是持续风格曝露。","textbook":"《主动投资组合管理》"}]},{"name":"固定收益债券与公司估值建模","goal":"掌握债券久期风险控制以及企业主流估值方法论","topics":[{"title":"债券定价、信用评级利差与违约回收率评估","intro":"理解债券票息与市场利率反向运动规律，掌握信用债违约条款与保障倍数体检逻辑。","textbook":"《固定收益证券手册》（法博齐）"},{"title":"债券久期与凸性：利率冲击下如何测算组合跌幅并进行免疫","intro":"久期近似代表利率变动 1% 时债券净价的反向百分比跌幅，是固收风控核心参数。","textbook":"《债券市场：分析与策略》"},{"title":"企业自由现金流折现（DCF）估值建模关键假设剖析","intro":"把增长率、加权资本成本 WACC 与永续增速敏感性放进估值表格，看清模型对假设的极高敏感度。","textbook":"《估值》（达摩达兰）"},{"title":"相对估值法应用：PE、PB、EV/EBITDA 与行业生命周期匹配","intro":"学会结合 ROE、成长阶段及周期位置选择恰当倍数，警惕低估值周期顶部价值陷阱。","textbook":"《投资估值实务》"}]},{"name":"公司金融决策与资本运作实务","goal":"从企业 CFO 视角平衡融资成本、分红激励与并购整合","topics":[{"title":"MM 定理与最优资本结构：税盾利益与财务困境权衡","intro":"明白适度举债可享利息税盾且防股权稀释，但过度高杠杆在景气下行期会加速破产失血。","textbook":"《公司财务原理》（布雷利、迈尔斯）"},{"title":"股利政策、股票回购与管理层激励治理陷阱","intro":"评估现金分红、注销式回购和在手闲置资金低效并购各自向市场传递的价值信号。","textbook":"《公司治理教程》"},{"title":"兼并与收购（M&A）交易架构、商誉减值与反收购条款","intro":"核算并购协同效应是否真能覆盖溢价收购成本，关注商誉占净资产比例暴雷警戒线。","textbook":"《兼并与收购》（帕特里克）"},{"title":"风险投资 VC/PE 融资条款：估值对赌、优先清算权与退出路径","intro":"理解一级市场从天使轮、Pre-IPO 到 IPO 锁定期背后的估值博弈与反稀释保护条文。","textbook":"《风投运作实务》"}]},{"name":"金融衍生品定价与系统风控引擎","goal":"拆解期货期权杠杆与对冲逻辑，建立不可逾越的风控底线","topics":[{"title":"远期与期货合约机制：保证金杠杆、基差变动与套期保值","intro":"企业运用期货锁定未来原材料成本并非为了赌涨跌，而是为了烫平现货利润巨幅波动。","textbook":"《期权、期货及其他衍生产品》（约翰·赫尔）"},{"title":"期权 payoff 结构与买方卖方非对称风险认知","intro":"清晰拆解看涨/看跌期权行权价与期权费逻辑，明白期权卖方收益封顶而尾部亏损无限。","textbook":"《期权投资策略》"},{"title":"BSM 定价思维与希腊字母（Delta/Gamma/Vega/Theta）直觉","intro":"读懂隐含波动率如何影响时间价值消耗，感受波动率飙升对衍生品头寸的非线性冲击。","textbook":"《金融工程》（洛伦兹·格利茨）"},{"title":"在险价值 VaR、压力测试与金融衍生品爆仓反思录","intro":"通过 99% 置信区间回测加上黑天鹅极端情景压测，杜绝「平常赚小钱、极值亏光本金」策略。","textbook":"《风险管理与金融机构》"}]},{"name":"金融科技、普惠配置与合规实战","goal":"构建家庭与机构稳健资产配置框架，辨别伪金融风险陷阱","topics":[{"title":"大类资产配置实战：全天候风险平价与股债平衡再平衡纪律","intro":"借助股票、国债、商品低相关性跨越牛熊，靠纪律化定期再平衡被动完成高抛低吸。","textbook":"《资产配置实战指南》（大卫·斯文森）"},{"title":"智能投顾、量化交易与供应链金融数字化应用","intro":"理解算法下单滑点、冲击成本与供应链核心企业确权应收账款如何帮助小微降融资门槛。","textbook":"《金融科技概论》"},{"title":"金融合规与反欺诈常识：庞氏结构拆解与非吸风险识别","intro":"牢记「高收益、零风险、拉人头返现」不可能三角，对场外高息理财保持铁律警惕。","textbook":"《金融监管与消费者保护》"},{"title":"个人/企业综合投资策略书撰写与历史回测复盘","intro":"独立挑选标的范围，产出包含收益拆解、最大回撤控制与退出机制的完整配置报告。","textbook":"《投研实战方法论》"}]}]},"管理学":{"stages":[{"name":"管理学基石与古典到现代思想演进","goal":"看透组织为何需要协同，掌握四大基础管理职能全景","topics":[{"title":"管理职能框架：计划、组织、领导与控制四大核心循环","intro":"管理的核心在于通过他人把事情既「做对（效率）」又「做正确（效能）」的协同过程。","textbook":"《管理学》（周三多主编，高等教育出版社）"},{"title":"古典管理与行为科学流派：泰勒科学管理到霍桑实验","intro":"从标准流水线工序拆解走到关注员工非正式群体、归属感与心理契约的现代组织观。","textbook":"《管理学》（斯蒂芬·罗宾斯，中国人民大学出版社）"},{"title":"决策理论核心：理性人假设、有限理性与满意准则（西蒙）","intro":"现实管理者难以遍历全部选项，掌握在约束时间内基于核心指标做出「足够好」决策的能力。","textbook":"《管理行为》（赫伯特·西蒙）"},{"title":"目标管理与战略解码：OKR 与 KPI 的适用边界及反噬治理","intro":"KPI 守底线保确定性执行，OKR 聚高远拉齐跨部门攻坚；慎防指标异化导致动作变形。","textbook":"《衡量什么最重要》（约翰·杜尔）"}]},{"name":"组织结构设计与组织行为学洞察","goal":"依据业务不确定性匹配高效率阵型并激发人性主动性","topics":[{"title":"组织架构演进：职能制、事业部制、矩阵式与敏捷团队","intro":"清晰界定纵向汇报权责与横向项目协作冲突，理解矩阵架构为何要求配套成熟协同机制。","textbook":"《组织结构设计》（明茨伯格）"},{"title":"组织行为学个体层面：动机双因素理论与公平感契约","intro":"保健因素没给够会立刻引发不满，但只有成就成长空间等激励因素能让人长期全力投入。","textbook":"《组织行为学》（罗宾斯）"},{"title":"领导力模型演进：权变领导、变革型领导与授权赋能边界","intro":"随下属能力意愿四象限动态切换指令/教练/支持/授权风格，而非固定单一管家式霸权。","textbook":"《领导力：如何在组织中成就卓越》"},{"title":"组织文化塑造与变革阻力化解（科特变革八步法）","intro":"变革常失败在低估既得惯性与安全焦虑，需借紧急危机共识、早期快赢与制度巩固平稳过桥。","textbook":"《领导变革》（约翰·科特）"}]},{"name":"竞争战略分析与商业模式设计","goal":"用宏观外视与资源内省框架制定不可轻易模仿的护城河","topics":[{"title":"行业吸引力与战略位置：PESTEL、波特五力与价值链分解","intro":"剖析供应商、买家、替代品及潜在进入者五股力量，找准自身利润池在链条中的真正高地。","textbook":"《竞争战略》（迈克尔·波特）"},{"title":"资源基础观与核心竞争力（VRIO 框架）：识别真壁垒","intro":"看一项优势是否真正持久，需逐项校验其稀缺性、高价值、不可轻易模仿与组织承接力。","textbook":"《战略管理》（迈克尔·希特）"},{"title":"商业模式画布拆解与第二增长曲线转型时机","intro":"厘清客户细分、价值主张、渠道成本结构间的因果飞轮，在第一曲线尚未见顶时提前孵化新局。","textbook":"《商业模式新生代》"},{"title":"增长扩张与多元化边界：纵向整合与轻资产外包决策","intro":"平衡核心能力控盘需要与外包交易成本，警惕脱离主业盲目跨界带来的管理失控陷阱。","textbook":"《蓝海战略》"}]},{"name":"运营管理、供应链协同与项目管理","goal":"消除流程浪费与瓶颈卡点，保证战略规划按时保质落地","topics":[{"title":"运营与瓶颈控制：精益生产、六西格玛与约束理论（TOC）","intro":"全局产出速度永远取决于最窄那道瓶颈工序；先疏通瓶颈并消减无效库存方能真提效。","textbook":"《目标》（高德拉特）与《运营管理》"},{"title":"供应链韧性、长鞭效应治理与库存 EOQ 经济订货","intro":"信息逐层延迟与放大催生上游剧烈波动，通过实时销量共享与协同补货稳住安全库存。","textbook":"《供应链管理：战略、规划与运作》"},{"title":"项目管理铁三角与敏捷迭代：关键路径法 CPM 与风险矩阵","intro":"在范围、时间与成本三角约束中追踪关键零浮动路径，用迭代评审早暴露早纠偏。","textbook":"《PMBOK 项目管理知识体系指南》"},{"title":"绩效复盘与流程持续改进（PDCA 与复盘四步曲）","intro":"严格区分目标回顾、过程还原、归因规律提炼与行动落地，拒绝把复盘办成批斗甩锅大会。","textbook":"《复盘+》（邱昭良）"}]},{"name":"人力资源开发、人才梯队与薪酬激励","goal":"打通选育用留人才全链路，把团队潜力转化为可持续组织能力","topics":[{"title":"精准选才：胜任力冰山模型与结构化行为面试法 STAR","intro":"简历文字只能测表面学历，需深挖候选人在过去真实困境中的具体动作来预判未来表现。","textbook":"《招聘面试官实战指南》"},{"title":"薪酬与股权激励架构：外部公平、内部层级与中长期绑定","intro":"组合固定基本薪、浮动绩效与期权限制股，兼顾短期攻坚激励与长期留任利益一致。","textbook":"《薪酬管理》（米尔科维奇）"},{"title":"团队高绩效协同（Lencioni 五大障碍）与非暴力沟通反馈","intro":"直面建立信任与建设性冲突前提，学会利用 SBI（情境-行为-影响）模型做对事不对人的反馈。","textbook":"《团队协作的五大障碍》"},{"title":"人才盘点九宫格与关键岗位继任梯队构建","intro":"以业绩与潜力双维评估精准识别高潜核心骨干，并提前铺设 B 角避免关键一人离职全线停摆。","textbook":"《人力资源管理》（加里·德斯勒）"}]},{"name":"数智时代管理创新与全案例沙盘复盘","goal":"在数字化组织与复杂市场不确定性中独立统筹全局管理项目","topics":[{"title":"数据驱动决策与业务指标仪表盘设计：北极星指标体系","intro":"剔除自嗨式虚荣指标，选取真正映射用户留存价值与商业变现的核心北极星牵引全局。","textbook":"《精益数据分析》"},{"title":"危机领导力与组织韧性：黑天鹅现金流预案及敏捷转型","intro":"构建分级预警应急预案，平时留出战略缓冲资源以应对供应链断供或需求骤变。","textbook":"《韧性组织管理》"},{"title":"跨文化沟通与 ESG 企业社会责任治理融入主营流程","intro":"把员工多元包容、环保碳足迹与诚信合规纳入长期品牌信誉与合规准入加分项。","textbook":"《跨文化管理实战》"},{"title":"企业诊断综合实战案例分析：财务、战略、组织协同诊治","intro":"剖析一家陷入增长停滞的企业全套材料，提交涵盖组织重构、运营增效与现金流改善的系统方案。","textbook":"《哈佛商业评论经典案例选读》"}]}]},"教育学":{"stages":[{"name":"教育学基石、培养目标与中外教育史","goal":"理解教育与个体成长、社会演进的根本关系及经典思想源流","topics":[{"title":"教育学基本概念：教育本质、功能与人的全面发展学说","intro":"区分广义与狭义学校教育，理解个体主观能动性与环境、遗传共同推动身心发展。","textbook":"《教育学基础》（全国十二所重点师范大学联合编写）"},{"title":"中国传统教育智慧：孔子因材施教、学记与书院讲学精神","intro":"提炼「不愤不启、循序渐进、教学相长」等跨越千年的育人原则并用于当代课堂对照。","textbook":"《中国教育史》（孙培青主编，华东师范大学出版社）"},{"title":"西方教育思想演进：夸美纽斯、卢梭、赫尔巴特与杜威革新","intro":"梳理班级授课制确立到杜威「教育即生活、做中学」以学生为中心范式转向的深层动力。","textbook":"《外国教育史教程》（吴式颖，人民教育出版社）"},{"title":"当代教育制度、教育公平指标与终身学习体系","intro":"分析九年义务教育均衡配置、双减政策背景与学习型社会微证书/学分银行趋势。","textbook":"《教育政策与制度导论》"}]},{"name":"学习科学核心与认知发展心理机制","goal":"告别盲目刷题与死记硬背，用实证脑科学与认知负荷指导教与学","topics":[{"title":"学习理论全景：建构主义、社会观察学习与支架式教学","intro":"知识不是被灌入空瓶而是学习者在旧经验上主动搭建脚手架建构的结果，适时撤梯方能独立。","textbook":"《当代教育心理学》（陈琦、刘儒德，北京师范大学出版社）"},{"title":"认知负荷理论与工作记忆瓶颈：如何把难点切碎好懂","intro":"区分内在、外在和相关认知负荷，尽量砍掉杂乱版面干扰、用可视化块化减轻记背压力。","textbook":"《学习科学与教学设计》（R.E. Mayer）"},{"title":"记忆提取强化规律：间隔重复、提取练习与交错学习","intro":"测试测验本身是最强记忆加速器；分散间隔复习与跨题型交错练习远胜整夜突击。","textbook":"《认知天性》（Make It Stick）"},{"title":"学习动机激发与自我调节学习：成长型思维与元认知监控","intro":"称赞具体策略与努力而非空泛「你真聪明」，训练学生自己制定计划、自查盲区与调适焦虑。","textbook":"《终身成长》（卡罗尔·德韦克）"}]},{"name":"课程论框架与高质量教学设计实务","goal":"掌握大单元逆向教学设计，能够写出重难点突破清晰的好教案","topics":[{"title":"课程开发四大要素与布鲁姆认知目标分类阶梯","intro":"明确记住、理解、应用、分析、评价与创造六个层次，让教学目标可观察、可评测。","textbook":"《课程与教学论》（钟启泉）"},{"title":"逆向教学设计（UbD）：以终为始先行规划评价证据","intro":"先问「学完要能解决什么真问题」并设定评估任务，最后倒推每节课要讲的活动和材料。","textbook":"《追求理解的教学设计》（威金斯）"},{"title":"多样化教学模式选择：PBL 项目式学习与探究合作课堂","intro":"围绕真实开放驱动问题设计小组分工与中期展示节点，防课堂流于热闹表面形式。","textbook":"《项目式学习实战手册》"},{"title":"微格教案撰写与优质板书/多媒体视觉支架规范","intro":"合理调度导入激趣、讲授精要、变式操练与迁移总结节奏，用好图示帮学生建立体系全景。","textbook":"《教学设计实操技能教程》"}]},{"name":"课堂管理、师德规范与教育测量评价","goal":"处理复杂课堂行为冲突，构建发展性而非贴标签的学业评估体系","topics":[{"title":"班级管理、积极行为支持与青春期学生心理沟通","intro":"用明确共创班规与非公开温和纠偏护住学生尊严，识别学习厌倦背后的受挫或家庭诱因。","textbook":"《班主任工作技能与艺术》"},{"title":"教师职业道德与校园安全法律边界：依法执教守则","intro":"恪守严禁有偿补课、体罚变相惩罚及尊重学生人格隐私等法律红线，建立家校平等协同。","textbook":"《教师专业伦理与法规》"},{"title":"形成性评价 vs 总结性评价与表现性量规（Rubric）设计","intro":"不止给冷冰冰的分数，还要给出清晰量规维度的诊断性反馈告诉学生具体从哪步改起。","textbook":"《教育评价学》（陈玉琨）"},{"title":"命题技术与试卷分析：难度、区分度与薄弱项闭环诊断","intro":"统计题目区分度与选项干扰项分布，用错误模式识别群体概念性迷思（Misconceptions）。","textbook":"《教育统计与测评技术》"}]},{"name":"教育技术融合与实证教育研究方法","goal":"会用实证调研与智慧数字工具评估教学改进效果","topics":[{"title":"教育研究选题、文献综述与行动研究法实战","intro":"聚焦一线真实教学痛点提出研究问题，沿计划-行动-观察-反思螺旋迭代优化方案。","textbook":"《教育研究方法导论》（裴娣娜，安徽教育出版社）"},{"title":"课堂观察量表、半结构化访谈与质性编码分析","intro":"客观记录师生活动时间与提问认知层次分布，从学生访谈逐字稿中归纳深层障碍。","textbook":"《质性研究方法与案例》"},{"title":"教育技术与多媒体认知原则（Mayer）：图文空间临近与防冗余","intro":"同一屏不要同时放长段整段念白和复杂无关动画，把文字说明直接贴近图表对应部位。","textbook":"《多媒体学习》"},{"title":"AI 赋能个性化学习路径与学术诚信边界指南","intro":"善用 AI 助教定制分层变式练习与苏格拉底式提示，同时教会学生核查与原创思考规范。","textbook":"《智能时代教师数字素养指南》"}]},{"name":"学科融合说课、模拟授课与综合研习","goal":"完成一堂从设计、试讲、测评到反思全闭环的高水准精品课","topics":[{"title":"专业说课框架实战：说教材、说学情、说目标重难点及教法流程","intro":"用 10 分钟向评委或教研组讲清设计背后的学理依据，而非干巴巴复述上课逐字稿。","textbook":"《卓越教师说课实战》"},{"title":"高质量试讲与无生课堂突发应对：节奏把控与互动模拟","intro":"在有限时间里模拟设疑、停顿、点评追问与板书呼应，展现笃定、亲和与学科专业气场。","textbook":"《中小学/高校教学竞赛指南》"},{"title":"融合教育与特殊需要学生差异化支持策略（UDL 通用设计）","intro":"为不同感知偏好和读写步调的学生提供多通道呈现与表达脚手架，真正落实有教无类。","textbook":"《特殊与融合教育概论》"},{"title":"完整教研案例包提交与教改反思答辩实操","intro":"汇总学情问卷数据、UbD 教学设计稿、学生作品反馈及改良方案完成教研全流程实战。","textbook":"《教学改革实训指导书》"}]}]},"英语":{"stages":[{"name":"语音重塑与实用核心语法框架","goal":"摆脱中式发音和破碎句法，建立地道语调节奏与句子骨架意识","topics":[{"title":"英语音系与语流音变：元辅音精度、重音节拍、连读与弱读","intro":"英语以重音计时而非音节均长，掌握连读、失爆与弱读规律是听懂母语者快语速的关键钥匙。","textbook":"《英语语音学》（孟宪忠 / Roach）"},{"title":"词根词缀高频扩词法与学术搭配（Collocation）习惯","intro":"按拉丁希腊词根网络记忆代替孤立逐字母拼写，并注重动词与介词地道固定搭配避免中式直译。","textbook":"《英语词汇学》（陆国强）"},{"title":"英语句法内核：五大基本句型、时态体系统整与情态推演","intro":"用「时间（过去/现在/将来）× 体貌（一般/进行/完成）」矩阵一次性厘清所有高频动词变化。","textbook":"《实战英语语法》（张道真 / Raymond Murphy）"},{"title":"从句与非谓语高阶整合：定语、名词性与状语从句辨析","intro":"学会识别长难句里的主干剥离与分词/不定式省略结构，为快速精准精读打通障碍。","textbook":"《旋元佑文法》"}]},{"name":"高效听说输入与日常/校园流利表达","goal":"突破听不懂不敢说哑巴瓶颈，建立多场景自然口语回应力","topics":[{"title":"影子跟读法（Shadowing）与可理解输入盲听精听四步流","intro":"依托 i+1 难度原声逐句听写盲点并紧贴半拍模仿语调重音，打通耳朵辨音到口腔输出的通路。","textbook":"《二语习得原声输入实践指南》"},{"title":"日常高频沟通功能句块：观点同意/缓和反驳与场景救急表达","intro":"摆脱单调 Yes/No，积累地道口语衔接词与委婉异议框架以保持谈话自然延续。","textbook":"《剑桥日常地道口语精讲》"},{"title":"听力抓重点信息与康奈尔笔记速记符号系统","intro":"听演讲与长对话时紧抓转折、因果、举例提示词，并用简化符号瞬间记录逻辑关系。","textbook":"《英语中高级听力笔记训练》"},{"title":"英语即兴演讲结构与发音清晰度打磨：PREP 表达法则","intro":"按观点-理由-例证-重申四段式组织口语作答，稳定实现一分钟有条理的脱稿陈述。","textbook":"《公众演讲技巧》（Stephen Lucas）"}]},{"name":"外刊深读、修辞赏析与长难句快速拆解","goal":"具备无障碍阅读经济学人级原版外刊与经典原著的视野深度","topics":[{"title":"学术外刊高效阅读法：寻读定位、略读主旨与段落主干抓拍","intro":"通过首尾句与路标词迅速搭建文章骨架，学会跳开枝叶修饰在限定时间内提取核心论点。","textbook":"《外刊经贸与时政精读实训》"},{"title":"长难句主干剥离术：倒装、强调、插入语与多层嵌套拆解","intro":"按意群标点与关系代词划断层次，把 60 词超级长句还原为清晰的主谓宾主从分支图。","textbook":"《英语阅读长难句突破》"},{"title":"英语文本修辞、隐喻及作者隐含立场批判性阅读","intro":"分辨客观事实陈述与倾向性形容词、反讽引号及预设结论，看懂评论文章真正的倾向性。","textbook":"《思辨英语阅读教程》"},{"title":"英美文学经典导读与文化典故源头溯源","intro":"了解希腊神话与圣经典故对现当代英语高频惯用表达的深刻影响，提升文本共情力。","textbook":"《英美文学简史与选读》（常耀信）"}]},{"name":"英汉双语互译与语篇衔接规范","goal":"克服中式译腔，做到理解准确且符合目标语言自然习惯","topics":[{"title":"英译汉核心转换术：顺译拆句、主被动语态切换与词性转译","intro":"英语重形合多用名词与被动，汉语重意合多用动词短句；切忌逐词对应产生拗口欧化长句。","textbook":"《实用英汉翻译教程》（叶子南）"},{"title":"汉译英攻坚技法：无主句补足、意合拆散转形合及定状安排","intro":"面对中文四字流水句学会先抓真正施事主语和主干动作，其余修饰用从句或介词短语挂靠。","textbook":"《汉译英实战技巧》（张培基）"},{"title":"跨文化惯用表达与本地化信达雅权衡实战","intro":"处理习语典故与官方公文时结合受众场景抉择直译加注还是意译替换，保原汁亦保可读性。","textbook":"《跨文化交际与翻译导论》"},{"title":"口译视译起步：意群切分顺驱技巧与数字日期瞬间反应","intro":"训练目光超前扫视并顺句切块口述的能力，克服强行倒装调整语序导致的瞬时卡壳。","textbook":"《高级视译实战》"}]},{"name":"学术论文写作、商务邮件与修辞论证","goal":"掌握符合国际期刊及专业职场标准的地道英文书面产出能力","topics":[{"title":"职场商务邮件写作：高效率主旨、请求得体与礼貌拒绝模版","intro":"开头开门见山亮明诉求，主体分条编号方便对方 10 秒看懂待办事项与期限。","textbook":"《国际商务英文沟通实务》"},{"title":"英文议论文段落展开：TEEL 结构、衔接词与同义替换多样化","intro":"确保每个自然段仅锚定单一中心主题句并配足论据，合理用指代过渡提高文气流畅度。","textbook":"《风格的要素》（Strunk & White）"},{"title":"学术写作规范（EAP）：文献改写 Paraphrase、客观学术语气与 APA/MLA","intro":"消除口语缩写词和极端绝对词（always/prove），用严谨转述和规范引注杜绝无意抄袭隐患。","textbook":"《学术英语写作教程》（Swales & Feak）"},{"title":"专业文书打磨与自改纠错清单：主谓一致、冠词与逻辑跳跃","intro":"学会运用逆向通读及朗读自检找出常见隐形语法错和逻辑断裂，交付高完成度文稿。","textbook":"《英文写作自检指南》"}]},{"name":"高阶考试冲刺、跨文化项目与自由表达实战","goal":"面向雅思/托福/考研/职场高阶场景形成可持续独立进修能力","topics":[{"title":"跨文化职场协作与国际会议发言：提问、打断礼仪与共识推进","intro":"在全英文跨国会议上恰当接话、汇总异议并清晰确认下步责任分工（Action Items）。","textbook":"《全球职场跨文化英语实战》"},{"title":"学术演讲与英文 PPT 视觉陈述逻辑：数据趋势精准描述","intro":"熟练掌握描述飙升、平台停滞、温和下跌等英文趋势动词及饼图对比表达。","textbook":"《英文学术报告演示艺术》"},{"title":"英文信息检索与一手英文原版资料高效调研流程","intro":"直接用精准英语关键词检索国际期刊论文与官方文档，突破二手中文译文的信息折损。","textbook":"《英文一手文献研究方法》"},{"title":"综合双语项目成果输出与个人语言学习长效维护机制","intro":"完成一份包含原版文献综述、英文展示讲稿及中英对照摘要的综合双语项目作品集。","textbook":"《高阶二语习得与自我测评》"}]}]},"人工智能":{"stages":[{"name":"数学底座与科学计算编程筑基","goal":"夯实线代概率微积分直觉与 Python 向量化高效编程底座","topics":[{"title":"线性代数与矩阵几何直觉：特征向量、SVD 奇异值分解与张量运算","intro":"把神经网络权重乘法看作高维空间旋转缩放投影；SVD 是降维压缩与低秩 LoRA 微调核心灵感。","textbook":"《线性代数及其应用》（Gilbert Strang）"},{"title":"概率统计与信息论基础：贝叶斯公式、最大似然与交叉熵损失","intro":"条件概率结合先验不断随证据刷新后验信念；交叉熵直观衡量预测分布与真实标签差距。","textbook":"《概率论与数理统计》&《信息论基础》"},{"title":"多元微积分与自动微分原理：梯度下降、链式法则与反向传播","intro":"损失函数梯度指明最快升高方向，按负梯度小步更新参数即可顺着地形下探低谷极小值。","textbook":"《微积分本质与数值优化》"},{"title":"Python 与 NumPy/Pandas 向量化高效工程：告别低效 for 循环","intro":"利用广播机制与底层连续内存 C 阵列一次性批量算完整批样本矩阵，提升百倍运行效率。","textbook":"《利用 Python 进行数据分析》（Wes McKinney）"}]},{"name":"经典机器学习算法与工程评估体系","goal":"亲手跑通特征工程、正则化、决策树集成及防过拟合验证体系","topics":[{"title":"监督学习起步：线性/逻辑回归、L1/L2 正则化与偏差-方差权衡","intro":"欠拟合说明模型太简漏掉规律（高偏差），过拟合说明死背噪声（高方差）；正则化抑制参数爆炸。","textbook":"《机器学习》（周志华，清华大学出版社）"},{"title":"验证准则与数据泄露防范：交叉验证、ROC-AUC 与 F1 指标挑选","intro":"类别不平衡时不能只看准确率；标准化缩放必须只在训练集统计而绝不能偷看测试集。","textbook":"《统计学习方法》（李航，清华大学出版社）"},{"title":"树模型王者与集成学习：决策树信息增益、随机森林与 XGBoost","intro":"Bagging 多树并行降低方差，Boosting 串联接力逼近残差拟合，是表格预测最稳健基石。","textbook":"《Hands-On Machine Learning》（Aurélien Géron）"},{"title":"无监督探索：K-Means 聚类、PCA 主成分降维与异常点检测","intro":"在没有任何标注标签的数据集中发现群体自然分簇并压缩冗余高度相关维度。","textbook":"《模式识别与机器学习》（PRML）"}]},{"name":"深度学习核心架构与 PyTorch 工程实战","goal":"亲手构建多层网络、CNN 与序列模型，理解训练稳定性关键工程技巧","topics":[{"title":"PyTorch 动态计算图与神经网络全循环（Forward/Backward/Step）","intro":"从 Dataset 批次读取、清零梯度、前向算损、反向传播到优化器更新建立完备代码肌肉记忆。","textbook":"《动手学深度学习》（李沐等，人民邮电出版社）"},{"title":"梯度消失/爆炸破解与深度训练技巧：残差连接、LayerNorm 与 AdamW","intro":"跳跃残差连接为梯度修通直达浅层高速公路，自适应动量与归一化让百层网络稳定收敛。","textbook":"《深度学习》（Ian Goodfellow 花书）"},{"title":"计算机视觉主干演进：卷积神经网络 CNN、特征图与目标检测思想","intro":"卷积核局部感受野兼权值共享天然贴合图像平移不变性，从图像分类走向检测分割。","textbook":"《CS231n 斯坦福计算机视觉讲义》"},{"title":"序列建模与循环记忆演变：RNN 瓶颈、LSTM 门控到 Attention 觉醒","intro":"理解长文本顺序读入遗忘痛点，由此引出允许全序列任意两词直接对话的注意力机制。","textbook":"《自然语言处理综述》（Jurafsky & Martin）"}]},{"name":"Transformer 与大语言模型核心原理解析","goal":"彻底拆懂当下大模型底座：多头自注意力、分词、预训练到对齐","topics":[{"title":"Transformer 全景透视：QKV 自注意力、多头投影与旋转位置编码","intro":"每个 Token 计算对上下文其他词的 Query-Key 相关权重并按 Value 聚合，并发处理整句。","textbook":"《Attention Is All You Need》论文精读"},{"title":"分词器 BPE、KV Cache 显存推理加速与预训练缩放定律（Scaling Law）","intro":"生成下一词时缓存历史 Key/Value 避免重复计算，揭示参数量与数据规模驱动涌现规律。","textbook":"《大语言模型导论》（人大赵鑫团队）"},{"title":"后训练对齐：指令微调 SFT、RLHF 偏好对齐与 DPO 原理","intro":"区分预训练「背知识」、SFT「学会按格式对话」与 RLHF/DPO「对齐人类价值观与诚实边界」。","textbook":"《LLM Alignment 前沿综述》"},{"title":"高效参数微调实操：LoRA 低秩适配与 QLoRA 量化省显存方案","intro":"冻结原巨型权重仅训练旁路一对极小低秩矩阵 AB，让消费级单卡也能微调领域专有模型。","textbook":"《HuggingFace PEFT 官方实战指南》"}]},{"name":"RAG 检索增强、智能体 Agent 与多模态前沿","goal":"将裸模型升级为联网可查私有知识库、可调用外部工具的真生产力系统","topics":[{"title":"RAG 检索增强全链路：语义切分、向量嵌入混合检索与重排 Rerank","intro":"用精确 BM25 词匹配加语义向量双路召回后再重排精筛，让模型回答有据可循显著压低幻觉。","textbook":"《Retrieval-Augmented Generation 工程实战》"},{"title":"结构化输出、Function Calling 与 ReAct 智能体循环架构","intro":"让大模型按严格 JSON Schema 输出工具参数并沿「思考→调工具→观察结果→继续推理」闭环运行。","textbook":"《Building Effective Agents 工程指南》"},{"title":"多模态生成基石：CLIP 图文对齐、扩散模型（Diffusion）去噪生成","intro":"理解对比学习怎样把图片与文字拽入同一语义向量空间，以及迭代去噪生成高清图像过程。","textbook":"《多模态大模型技术手册》"},{"title":"模型推理部署与性能监控：vLLM 分页内存、量化加速与安全护栏","intro":"用 PagedAttention 提升并发吞吐，叠加输入输出审核护栏拦截提示词注入与敏感违规输出。","textbook":"《MLOps 生产运维实践》"}]},{"name":"端到端 AI 应用架构、评测基准与全栈上线","goal":"从算法实验跨入真实在线系统设计、评测体系建设与商业交付","topics":[{"title":"LLM 客观自动评测：基准集构建、LLM-as-a-Judge 与幻觉率监控","intro":"不要靠体感拍脑袋说新版本变聪明了，必须搭建黄金测试集量化追踪准确性与时延变化。","textbook":"《AI Evaluation 实战指南》"},{"title":"AI 应用成本与延迟架构权衡：模型路由分层与语义缓存","intro":"简单分类交给轻量小模型极速响应，复杂深度规划再调度旗舰推理模型，兼顾体验与算力账单。","textbook":"《大模型成本工程优化》"},{"title":"AI 伦理治理、数据隐私脱敏与可控可解释规范","intro":"遵守训练数据版权、个人敏感字段入模脱敏规范，在医疗金融高危场景坚持人工最终核准。","textbook":"《负责任人工智能治理纲要》"},{"title":"高可用 AI 垂直应用全栈实战：设计、评测、部署与压测上线","intro":"整合知识库 RAG、工具 Agent、流式 UI 与可观测性日志，独立上线完整可演示智能系统。","textbook":"《现代 AI 应用全栈项目实战》"}]}]},"机械工程":{"stages":[{"name":"工程图学、理论力学与机械材料基石","goal":"打通二维三视图与三维构型沟通语言，建立严谨静动力平衡观念","topics":[{"title":"画法几何与机械制图：正投影三视图、剖面视图与公差配合基准","intro":"做到图实互译，精准识读形位公差、表面粗糙度及基孔/基轴配合决定零件松紧装配质量。","textbook":"《机械制图》（大连理工大学，高等教育出版社）"},{"title":"理论力学核心：空间力系平衡、摩擦自锁与刚体定轴/平面运动","intro":"用隔离体画对受力图列平衡方程，理解斜面摩擦角自锁原理（千斤顶、螺纹防松源头）。","textbook":"《理论力学》（哈尔滨工业大学，高等教育出版社）"},{"title":"材料力学重点：拉压、剪切、扭转与梁的弯曲内力图分析","intro":"学会画剪力弯矩图找出最危险截面位置，通过截面对称惯性矩与合理配筋大幅增强抗弯刚度。","textbook":"《材料力学》（刘鸿文主编，高等教育出版社）"},{"title":"工程材料与热处理：铁碳相图、淬火回火渗碳对强韧性的调控","intro":"看懂低碳钢韧塑性与高碳钢硬脆性分工，利用表面热处理达成「外硬耐磨、心部抗冲击」。","textbook":"《机械工程材料》（王运炎）"}]},{"name":"机械原理机构运动与通用零部件设计","goal":"掌握四杆、凸轮、齿轮传动力学特性及标准紧固轴承选型","topics":[{"title":"机构自由度计算与平面连杆（曲柄摇杆/死点利用）设计","intro":"保证机构原动件数等于自由度才确定运动；理解死点位置既是卡死隐患也能用做夹紧机构。","textbook":"《机械原理》（孙桓、陈作模，高等教育出版社）"},{"title":"齿轮啮合传动与轮系减速箱：渐开线共轭、模数与变位原理","intro":"渐开线齿廓确保中心距微变时传动比依然恒定，学会计算定轴/周转行星轮系速比分配。","textbook":"《机械设计》（濮良贵、陈国定，高等教育出版社）"},{"title":"轴系结构设计与滚动轴承选型：强度刚度与轴向定位防干涉","intro":"综合弯扭合成当量应力计算阶梯轴径并留足圆角减小应力集中，合理配对角接触向心推力轴承。","textbook":"《机械设计手册精要》"},{"title":"带传动、链传动及螺栓连接预紧防松工程计算","intro":"明白带传动靠摩擦传动有过载打滑保护却存在弹性滑动误差，高振场景必配双螺母或弹簧垫防松。","textbook":"《通用机械零部件工程实例》"}]},{"name":"制造工艺、互换性测量与 CNC 数控加工","goal":"不仅能在电脑里画出完美三维模型，更能确保工厂经济合理做出来","topics":[{"title":"互换性与技术测量：尺寸链计算与基准重合工艺规范","intro":"用极值与概率尺寸链合理分配各道工序公差，避免公差太严报废翻倍或太松装不上。","textbook":"《互换性与技术测量》（廖念钊）"},{"title":"机械制造工艺学：车铣刨磨钻特征、定位六点原则与装夹基准","intro":"遵循「先基准后其他、先粗后精、先面后孔」工艺路线并严谨排除过定位引发的干涉变形。","textbook":"《机械制造工艺学》（王先逵）"},{"title":"数控加工（CNC）与 G 代码编程基础：刀具半径补偿与切削三要素","intro":"根据材料硬度与机床刚性合理配置主轴转速、进给量及切深，平衡表面质量与刀具寿命。","textbook":"《现代数控加工与编程实训》"},{"title":"面向制造与装配的设计（DFM/DFA）：防加工干涉与模具拔模","intro":"消除盲孔深内尖角等昂贵特种加工特征，用少件合并和防呆对称设计从源头砍掉装配错误。","textbook":"《面向制造与装配的产品设计》"}]},{"name":"CAD/CAE 仿真、有限元分析与流体传热","goal":"利用数字化三维建模与有限元软件提前在电脑中验证强度与热流","topics":[{"title":"三维参数化建模规范（SolidWorks/UG）：全约束草图与自顶向下装配","intro":"建立清晰特征树与主控骨架草图，令单尺寸修改后整套装配体联动更新而不崩溃报错。","textbook":"《三维 CAD 参数化设计实战》"},{"title":"有限元分析（FEA）原理：网格收敛性、边界施加与应力集中甄别","intro":"避免直接迷信软件彩虹云图；警惕尖角假奇异应力并做不同网格密度的收敛稳定性校验。","textbook":"《有限元法基础与 ANSYS 实战》"},{"title":"流体力学与传热基础：伯努利原理、雷诺数及散热片热阻控制","intro":"理解层流与湍流边界层差异及强制风冷/液冷设计逻辑，防范精密主轴热变形降低精度。","textbook":"《工程流体力学与传热学》"},{"title":"液压与气压传动系统：泵阀缸回路、调速控制与防过载安全阀","intro":"识读换向阀机能与节流调速油路原理图，学会依据负载峰值与响应速度选配液控或气动执行器。","textbook":"《液压与气压传动》（左健民）"}]},{"name":"机电一体化、传感测控与 PLC/嵌入式控制","goal":"为静态钢铁机构注入电气控制与闭环大脑，迈向智能装备","topics":[{"title":"电工电子与驱动执行器：步进电机 vs 伺服电机闭环精度差异","intro":"明确异步/无刷/步进/伺服电机力矩-转速特性曲线，按负载惯量比精准选配编码器与减速机。","textbook":"《机电一体化系统设计》（张建民）"},{"title":"工业传感器与信号调理：光电开关、应变片与增量/绝对值编码器","intro":"针对温度、压力与微米位移选型合适传感器，做好电磁屏蔽滤波避免工业现场误触发信号。","textbook":"《传感器与检测技术》"},{"title":"经典控制理论直觉与 PID 闭环调参：比例、积分、微分各自职责","intro":"P 定快慢但留余差，I 消静差易超调振荡，D 抑冲过头保阻尼——三参合一稳稳贴合目标曲线。","textbook":"《自动控制原理》（胡寿松，科学出版社）"},{"title":"PLC 梯形图逻辑与工业总线通信（EtherCAT/Modbus）实操","intro":"掌握急停安全继电器互锁硬接线与多工位状态机编程思想，筑牢工业设备人身安全铁律。","textbook":"《现代 PLC 控制工程实务》"}]},{"name":"机器人机构、智能制造系统与综合设计实训","goal":"贯通机械结构、控制算法与生产节拍，独立完成全周期工程装备设计","topics":[{"title":"工业机器人运动学导论：DH 参数、正逆解与轨迹平滑插补","intro":"明白六轴机械臂奇异点卡滞风险，学习五次多项式插补规划让末端加速起停柔顺无冲击。","textbook":"《机器人学导论》（John Craig）"},{"title":"工业视觉引导与柔性装配工作站：相机标定与夹爪柔顺设计","intro":"串联 2D/3D 视觉定位偏移补偿与气动/电伺服夹爪力控逻辑，突破来料无序抓取痛点。","textbook":"《智能制造装备与系统集成》"},{"title":"可靠性工程、FMEA 失效模式分析与预防性维护体系","intro":"通过严重度、频度与探测度 RPN 评分前置排查机构关键薄弱链并制定点检更换周期表。","textbook":"《机械可靠性设计与 FMEA 实务》"},{"title":"典型智能机电装备综合毕业级设计：从指标需求到全套图档输出","intro":"围绕给定节拍与载荷指标完成方案比选、三维装配、校核计算书、BOM 与工艺卡闭环交付。","textbook":"《机械工程综合设计实训指南》"}]}]}};

const POSITIVE_REPO_RE = /\b(curriculum|syllabus|course|roadmap|awesome|university|notes|guide|study|tutorial|textbook|open-?course|learning|ossu)\b|课程|大纲|指南|学习|笔记|教材|体系|教程/i;
const NEGATIVE_REPO_RE = /\b(crack|keygen|cheat|spam|bot|airdrop|casino|resume-template|hello-world|mind-expanding-books|social-engineering|awesome-tech-rss|free-ebook|pdf-download)\b|PDF下载|网盘|百度云|免费下载|电子书合集/i;
const SKIP_HEADING_RE = /^(table of contents|contents|contributing|contribute|license|acknowledg|sponsor|credits|star history|citation|changelog|faq|about|contact|related repos|目录|致谢|贡献|开源协议|版权|赞助|更新日志)$/i;
const GENERIC_STEM_STOPWORDS = new Set(['the', 'and', 'for', 'with', 'course', 'curriculum', 'study', 'notes', 'major', 'intro', 'introduction', '101', 'awesome', 'guide', 'tutorial']);

const slotStates = new Map();
let rrCursor = 0;

function printHelp() {
  console.log(`慧学导师 · 权威课程检索与定纲 CLI (research-syllabus.mjs)

用法:
  node research-syllabus.mjs --major "<专业或领域>" [选项]
  node research-syllabus.mjs --list-disciplines [--json]

选项:
  --major "<名>"         目标专业或跨学科主题（如 "心理学"、"法学"、"量化金融"）
  --depth <mode>         comprehensive (6阶段×4节=24点，默认) | concise (期末速成 3×3=9点)
  --offline              仅使用离线内置 26 学科词库与 12 门高校级骨架，不发网络请求
  --force-live           跳过新鲜缓存强制联网重查（仍保留 ETag 304 省配额）
  --cache-dir <path>     本地 ETag 缓存目录（默认 ~/.huixue-mentor/cache）
  --json                 输出机器可读 JSON
  --list-disciplines     列出内置 26 大学科检索键与 12 门 6×4 旗舰大纲
`);
}

function parseArgs(argv) {
  const flags = new Map();
  const bools = new Set();
  const args = argv.slice(2);
  for (let i = 0; i < args.length; i++) {
    const t = args[i];
    if (!t.startsWith('--')) continue;
    const eq = t.indexOf('=');
    if (eq > 0) {
      flags.set(t.slice(2, eq), t.slice(eq + 1));
    } else if (args[i + 1] !== undefined && !args[i + 1].startsWith('--')) {
      flags.set(t.slice(2), args[++i]);
    } else {
      bools.add(t.slice(2));
    }
  }
  return { flags, bools };
}

function matchMajorEntry(major) {
  const clean = String(major || '').trim();
  for (const item of MAJOR_QUERY_BANK) {
    if (item.match.test(clean)) return item;
  }
  return null;
}

function buildGitHubQueries(major) {
  const clean = String(major || '').trim();
  const matched = matchMajorEntry(clean);
  if (matched) return matched.queries;
  return [`${clean} curriculum`, `${clean} 课程`];
}

function extractCustomMajorStems(major) {
  const clean = String(major || '').trim();
  if (!clean) return [];
  const stems = [];
  for (const m of clean.matchAll(/[a-zA-Z]{2,}/g)) {
    const w = m[0].toLowerCase();
    if (!GENERIC_STEM_STOPWORDS.has(w)) stems.push(w);
  }
  for (const m of clean.matchAll(/[\u4e00-\u9fa5]{2,}/g)) {
    const zh = m[0].replace(/(专业|课程|导论|基础|学)$/g, '').trim() || m[0];
    stems.push(zh);
    if (zh.length >= 3) {
      for (let i = 0; i <= zh.length - 2; i++) stems.push(zh.slice(i, i + 2));
    }
  }
  return [...new Set(stems)].filter(s => s.length >= 2);
}

export function scoreGitHubRepo(repo, matchedEntry = null, cleanMajor = '') {
  if (!repo || repo.archived || repo.disabled) return -1;
  const stars = Number(repo.stargazers_count || 0);
  const text = `${repo.full_name || ''} ${repo.description || ''} ${(repo.topics || []).join(' ')}`;
  if (NEGATIVE_REPO_RE.test(text)) return -1;

  if (matchedEntry) {
    if (matchedEntry.excludeMatch && matchedEntry.excludeMatch.test(text)) return -1;
    if (matchedEntry.mustMatch && !matchedEntry.mustMatch.test(text)) return -1;
  } else if (cleanMajor) {
    const stems = extractCustomMajorStems(cleanMajor);
    const lowerText = text.toLowerCase();
    if (stems.length > 0 && !stems.some(st => lowerText.includes(st))) return -1;
  }

  let score = Math.log10(stars + 10) * 3.2;
  if (POSITIVE_REPO_RE.test(text)) score += 3.5;
  if ((repo.description || '').trim().length > 15) score += 0.8;
  if (stars >= 100) score += 1.5;
  if (stars >= 1000) score += 2.0;
  return Number(score.toFixed(2));
}

function stripExternalAttributions(text) {
  return String(text || '')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
    .replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, '$1')
    .replace(/https?:\/\/(?:github\.com|raw\.githubusercontent\.com|shields\.io|img\.shields\.io)\S+/gi, '')
    .replace(/\bGitHub\b/gi, '')
    .replace(/<[^>]+>/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

export function extractSyllabusFromMarkdown(markdown) {
  const lines = String(markdown || '').replace(/\r\n/g, '\n').split('\n');
  const headings = [];
  const bullets = [];
  const books = new Set();
  const seenH = new Set();
  const seenB = new Set();
  let skip = false;

  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line) continue;
    const hm = line.match(/^#{1,4}\s+(.+)$/);
    if (hm) {
      const cleanH = stripExternalAttributions(hm[1]).replace(/^[\d.、\s*-]+/, '').trim();
      if (!cleanH || SKIP_HEADING_RE.test(cleanH) || cleanH.length < 2 || cleanH.length > 60) {
        skip = SKIP_HEADING_RE.test(cleanH);
        continue;
      }
      skip = false;
      if (!seenH.has(cleanH) && headings.length < 36) {
        seenH.add(cleanH);
        headings.push(cleanH);
      }
      continue;
    }
    if (skip) continue;

    for (const bm of line.matchAll(/《([^《》\n]{2,40})》/g)) books.add(bm[1].trim());

    const lm = line.match(/^[-*+]\s+(.+)$/);
    if (lm) {
      const cleanB = stripExternalAttributions(lm[1]).replace(/^[*s_-]+/, '').trim();
      if (cleanB.length >= 3 && cleanB.length <= 72 && !/^(star|fork|badge|pr|issue|mit|apache)/i.test(cleanB)) {
        const shortB = cleanB.split(/[：:—–|]/)[0].trim().slice(0, 48);
        if (shortB.length >= 2 && !seenB.has(shortB) && bullets.length < 48) {
          seenB.add(shortB);
          bullets.push(shortB);
        }
      }
    }
  }
  return { headings, bullets, textbooks: [...books].slice(0, 12) };
}

function findCuratedSyllabus(major) {
  const clean = String(major || '').trim();
  if (!clean) return null;
  if (CURATED_6STAGE_SYLLABI[clean]) return CURATED_6STAGE_SYLLABI[clean];
  for (const [k, val] of Object.entries(CURATED_6STAGE_SYLLABI)) {
    if (clean.includes(k) || k.includes(clean)) return val;
  }
  const matched = matchMajorEntry(clean);
  if (matched && CURATED_6STAGE_SYLLABI[matched.key]) return CURATED_6STAGE_SYLLABI[matched.key];
  return null;
}

function buildScaffold(major, digest, depth) {
  const curated = findCuratedSyllabus(major);
  let stages;

  if (curated?.stages?.length) {
    stages = curated.stages.map(st => ({
      name: st.name,
      goal: st.goal,
      topics: st.topics.map(tp => ({ title: tp.title, intro: tp.intro, textbook: tp.textbook })),
    }));
  } else {
    const pool = [...new Set([...(digest.headings || []), ...(digest.bullets || [])])].filter(x => x.length >= 2 && x.length <= 36);
    const default6 = [
      { name: `一、${major}学科导论与方法论根基`, goal: `建立${major}全貌视野、核心研究问题与基础工具` },
      { name: `二、${major}核心基础理论与底层概念`, goal: `夯实专业术语体系、基石公理与核心分析框架` },
      { name: `三、${major}分支体系与关键机制深入`, goal: `贯通主体知识脉络，把握模块间的协同与约束` },
      { name: `四、${major}交叉方法、定量工具与深度辨析`, goal: `掌握实证研究/工程工具链，能独立分辨易错前提` },
      { name: `五、${major}经典案例研习与复杂场景实务`, goal: `将理论落回行业与科研真实场景，形成解决思路` },
      { name: `六、${major}综合项目实践、学术写作与职业进阶`, goal: `产出完整专业成果，打通考证、深造与职业通道` },
    ];
    const slotTitles = [
      [`${major}学科边界、演进脉络与全局地图`, `${major}核心分析工具与研究范式入门`, `${major}高频专业术语与阅读解码法`, `${major}经典文献导读与学习路径搭建`],
      [`${major}底层核心公理与基本规律`, `${major}主要学派/核心框架横向对比`, `${major}关键机制的因果链条拆解`, `${major}基础模型构建与常见误区辨析`],
      [`${major}核心模块一：主体结构深入解析`, `${major}核心模块二：动态变化与制约边界`, `${major}核心模块三：跨模块耦合与衔接逻辑`, `${major}阶段性体系串联与知识网复盘`],
      [`${major}定量分析与专业工具实操入门`, `${major}多维对比判据与复杂情形推演`, `${major}典型反例与前沿争议问题辨析`, `${major}批判性思维与独立论证训练`],
      [`${major}经典实务案例全景拆解（上）`, `${major}多约束复杂问题建模与求解（下）`, `${major}行业规范、职业伦理与风控准则`, `${major}真实场景复盘与方案优化演练`],
      [`${major}综合性专题项目策划与执行`, `${major}学术研究方法、综述与论文写作规范`, `${major}核心资格考试/深造重难点梳理`, `${major}职业发展图谱与个人作品集构建`],
    ];
    let pIdx = 0;
    stages = default6.map((st, si) => ({
      name: st.name,
      goal: st.goal,
      topics: slotTitles[si].map(fallbackTitle => {
        const hint = pool[pIdx++];
        const title = hint && !/^stage|chapter|section|lesson/i.test(hint) && hint.length <= 28
          ? `${hint}（${si < 2 ? '基础核心' : si < 4 ? '进阶深化' : '实战专题'}）`
          : fallbackTitle;
        return {
          title,
          intro: `围绕「${title}」，系统理清其在${major}知识网中的核心作用、适用边界与实战应用。`,
          textbook: digest.textbooks?.[si % Math.max(1, digest.textbooks?.length || 0)] || `${major}核心经典教材（请核对院校指定版本）`,
        };
      }),
    }));
  }

  if (depth === 'concise') {
    const picked = stages.length >= 6 ? [stages[0], stages[2], stages[5]] : stages.slice(0, 3);
    return picked.map(st => ({ ...st, topics: st.topics.slice(0, 3) }));
  }
  return stages;
}

function resolveTokenList() {
  const combined = [process.env.GITHUB_TOKENS, process.env.GITHUB_TOKEN].filter(Boolean).join(',');
  if (!combined) return [];
  return [...new Set(combined.split(/[,;\s]+/).map(s => s.trim()).filter(Boolean))];
}

function buildSlotPool() {
  const tokens = resolveTokenList();
  const authSlots = tokens.map(tok => {
    const hash = crypto.createHash('sha256').update(tok).digest('hex').slice(0, 12);
    const key = `tok:${hash}`;
    if (!slotStates.has(key)) slotStates.set(key, { key, token: tok, isAuth: true, limitPerMin: 30, remaining: 30, resetAtMs: 0, blockedUntil: 0, invalid: false });
    return slotStates.get(key);
  });
  if (!slotStates.has('anonymous')) slotStates.set('anonymous', { key: 'anonymous', token: '', isAuth: false, limitPerMin: 10, remaining: 10, resetAtMs: 0, blockedUntil: 0, invalid: false });
  return { authSlots, anonSlot: slotStates.get('anonymous') };
}

function pickSearchSlot(pool, excludeKeys) {
  const now = Date.now();
  const availAuth = pool.authSlots.filter(s => !s.invalid && !excludeKeys.has(s.key) && s.blockedUntil <= now && s.remaining > 0);
  if (availAuth.length > 0) {
    const idx = rrCursor % availAuth.length;
    rrCursor = (rrCursor + 1) % 1_000_000;
    return availAuth[idx];
  }
  const anon = pool.anonSlot;
  if (!excludeKeys.has(anon.key) && anon.blockedUntil <= now && anon.remaining > 0) return anon;
  return null;
}

function updateSlotFromResponse(slot, res) {
  const now = Date.now();
  const rem = res.headers?.get?.('x-ratelimit-remaining');
  const reset = Number(res.headers?.get?.('x-ratelimit-reset') || 0);
  if (reset > 1e9) slot.resetAtMs = reset * 1000 + 1500;
  if (rem !== null && rem !== undefined && rem !== '') slot.remaining = Math.max(0, Number(rem));
  else if (res.ok && res.status !== 304) slot.remaining = Math.max(0, slot.remaining - 1);
  if (res.status === 403 || res.status === 429 || rem === '0') {
    slot.blockedUntil = Math.max(slot.blockedUntil, now + 60_000);
    if (res.status === 403 || res.status === 429) slot.remaining = 0;
  }
}

async function researchOnline(cleanMajor, matchedEntry, cacheFile, forceLive) {
  const now = Date.now();
  let prevEntry = null;
  if (fs.existsSync(cacheFile)) {
    try { prevEntry = JSON.parse(fs.readFileSync(cacheFile, 'utf8')); } catch {}
  }
  if (!forceLive && prevEntry?.corpus && Number(prevEntry.expiresAt || 0) > now) {
    return { ...prevEntry.corpus, cacheHit: 'fresh' };
  }

  const pool = buildSlotPool();
  const queries = buildGitHubQueries(cleanMajor);
  const prevQueryCache = prevEntry?.corpus?.queryCache || {};
  const nextQueryCache = { ...prevQueryCache };
  const candidateMap = new Map();
  let hadFailure = false;
  let etagHits = 0;

  const searchOnce = async q => {
    const apiUrl = `https://api.github.com/search/repositories?q=${encodeURIComponent(q)}&sort=stars&order=desc&per_page=8`;
    const prevCached = prevQueryCache[q];
    const excludeKeys = new Set();

    while (true) {
      const slot = pickSearchSlot(pool, excludeKeys);
      if (!slot) { hadFailure = true; return; }
      excludeKeys.add(slot.key);

      const headers = { 'User-Agent': 'Huixue-Mentor-Skill/1.0', Accept: 'application/vnd.github+json' };
      if (slot.token) headers.Authorization = `Bearer ${slot.token}`;
      if (prevCached?.etag) headers['If-None-Match'] = prevCached.etag;

      let res;
      try {
        res = await fetch(apiUrl, { headers, signal: AbortSignal.timeout(5500) });
      } catch {
        hadFailure = true;
        return;
      }

      if (res.status === 401 && slot.isAuth) { slot.invalid = true; continue; }
      updateSlotFromResponse(slot, res);

      if (res.status === 304 && Array.isArray(prevCached?.items)) {
        etagHits++;
        for (const repo of prevCached.items) {
          const sc = scoreGitHubRepo(repo, matchedEntry, cleanMajor);
          if (sc > 0 && !candidateMap.has(repo.full_name)) candidateMap.set(repo.full_name, { ...repo, _score: sc });
        }
        return;
      }
      if (res.status === 403 || res.status === 429) { hadFailure = true; continue; }
      if (!res.ok) { hadFailure = true; return; }

      const data = await res.json();
      const etag = res.headers?.get?.('etag') || '';
      const slimItems = Array.isArray(data?.items)
        ? data.items.slice(0, 8).map(r => ({ full_name: r.full_name, stargazers_count: r.stargazers_count, description: r.description, topics: r.topics, default_branch: r.default_branch }))
        : [];
      nextQueryCache[q] = { etag, items: slimItems };
      for (const repo of slimItems) {
        const sc = scoreGitHubRepo(repo, matchedEntry, cleanMajor);
        if (sc > 0 && !candidateMap.has(repo.full_name)) candidateMap.set(repo.full_name, { ...repo, _score: sc });
      }
      return;
    }
  };

  if (queries[0]) await searchOnce(queries[0]);
  if (candidateMap.size < 2 && queries[1]) await searchOnce(queries[1]);

  const ranked = [...candidateMap.values()].sort((a, b) => b._score - a._score).slice(0, 3);
  if (ranked.length === 0 && hadFailure && prevEntry?.corpus?.mode === 'github-live+synthesis') {
    return { ...prevEntry.corpus, cacheHit: 'stale-fallback' };
  }

  const readmeResults = [];
  if (ranked.length) {
    const settled = await Promise.allSettled(ranked.map(async repo => {
      const branch = repo.default_branch || 'main';
      const urls = [
        `https://raw.githubusercontent.com/${repo.full_name}/${encodeURIComponent(branch)}/README.md`,
        ...(branch !== 'master' ? [`https://raw.githubusercontent.com/${repo.full_name}/master/README.md`] : []),
      ];
      for (const u of urls) {
        try {
          const r = await fetch(u, { headers: { 'User-Agent': 'Huixue-Mentor-Skill/1.0' }, signal: AbortSignal.timeout(4500) });
          if (r.ok) {
            const md = (await r.text()).slice(0, 180 * 1024);
            if (md.trim().length > 80) return extractSyllabusFromMarkdown(md);
          }
        } catch {}
      }
      return extractSyllabusFromMarkdown(repo.description || '');
    }));
    for (const s of settled) if (s.status === 'fulfilled' && s.value) readmeResults.push(s.value);
  }

  const corpus = {
    mode: ranked.length ? 'github-live+synthesis' : 'curated-authority',
    repoCount: ranked.length,
    etagHits,
    extractedHeadings: [...new Set(readmeResults.flatMap(r => r.headings || []))].slice(0, 36),
    extractedTopics: [...new Set(readmeResults.flatMap(r => r.bullets || []))].slice(0, 48),
    extractedBooks: [...new Set(readmeResults.flatMap(r => r.textbooks || []))].slice(0, 12),
    queryCache: nextQueryCache,
  };

  try {
    fs.mkdirSync(path.dirname(cacheFile), { recursive: true });
    fs.writeFileSync(cacheFile, JSON.stringify({ corpus, expiresAt: now + FRESH_CACHE_TTL_MS, staleUntil: now + STALE_CACHE_TTL_MS }, null, 2), 'utf8');
  } catch {}

  return { ...corpus, cacheHit: 'live' };
}

function renderMarkdown(result) {
  const lines = [
    `# 🎓 《${result.major}》${result.depth === 'concise' ? '期末速成骨架（3×3）' : '系统登顶学习路线（6×4）'}`,
    '',
    `- **规范学科归类**：${result.canonicalKey || '跨学科/自定义方向'}`,
    `- **检索模式**：${result.mode} | **开源语料融合数**：${result.repoCount} | **缓存状态**：${result.cacheHit}`,
    `- **默认检索词线索**：${result.queries.map(q => '`' + q + '`').join(' / ')}`,
    '',
  ];
  if (result.extractedBooks?.length) {
    lines.push(`- **高星仓库关联经典书目**：${result.extractedBooks.map(b => '《' + b + '》').join('、')}`, '');
  }
  result.stages.forEach((st, idx) => {
    lines.push(`## 阶段 ${idx + 1}：${st.name}`);
    lines.push(`> 目标：${st.goal}`, '');
    st.topics.forEach((tp, ti) => {
      lines.push(`${ti + 1}. **${tp.title}** — ${tp.intro} *（参考：${tp.textbook}）*`);
    });
    lines.push('');
  });
  return lines.join('\n');
}

async function main() {
  const { flags, bools } = parseArgs(process.argv);
  if (bools.has('help') || bools.has('h')) {
    printHelp();
    return;
  }
  const asJson = bools.has('json');

  if (bools.has('list-disciplines')) {
    const out = {
      canonicalDisciplines: MAJOR_QUERY_BANK.map(item => ({ key: item.key, queries: item.queries })),
      curatedSyllabi: Object.keys(CURATED_6STAGE_SYLLABI),
    };
    if (asJson) console.log(JSON.stringify(out, null, 2));
    else {
      console.log('📚 内置 26 大学科规范检索词族：\n' + out.canonicalDisciplines.map((d, i) => `${i + 1}. ${d.key} [${d.queries.join(', ')}]`).join('\n'));
      console.log('\n🎓 内置 12 门高校级 6×4 旗舰课程大纲：\n' + out.curatedSyllabi.join('、'));
    }
    return;
  }

  const major = String(flags.get('major') || '').trim();
  if (!major) {
    printHelp();
    process.exit(1);
  }
  const depth = flags.get('depth') === 'concise' ? 'concise' : 'comprehensive';
  const offline = bools.has('offline');
  const forceLive = bools.has('force-live');
  const cacheDir = path.resolve(flags.get('cache-dir') || path.join(os.homedir(), '.huixue-mentor', 'cache'));

  const matchedEntry = matchMajorEntry(major);
  const queries = buildGitHubQueries(major);
  const cacheKey = matchedEntry ? `bank_${matchedEntry.key}` : `custom_${crypto.createHash('sha256').update(major.toLowerCase()).digest('hex').slice(0, 12)}`;
  const cacheFile = path.join(cacheDir, `${cacheKey}.json`);

  const corpus = offline
    ? { mode: 'offline-curated', repoCount: 0, etagHits: 0, extractedHeadings: [], extractedTopics: [], extractedBooks: [], cacheHit: 'offline' }
    : await researchOnline(major, matchedEntry, cacheFile, forceLive);

  const stages = buildScaffold(major, corpus, depth);
  const result = {
    major,
    canonicalKey: matchedEntry?.key || null,
    depth,
    queries,
    mode: corpus.mode,
    repoCount: corpus.repoCount,
    etagHits: corpus.etagHits || 0,
    cacheHit: corpus.cacheHit,
    extractedHeadings: (corpus.extractedHeadings || []).slice(0, 20),
    extractedTopics: (corpus.extractedTopics || []).slice(0, 24),
    extractedBooks: corpus.extractedBooks || [],
    stages,
  };

  if (asJson) console.log(JSON.stringify(result, null, 2));
  else console.log(renderMarkdown(result));
}

const isDirectRun = process.argv[1] && path.resolve(process.argv[1]) === path.resolve(fileURLToPath(import.meta.url));
if (isDirectRun) {
  main().catch(err => {
    console.error(JSON.stringify({ ok: false, error: err?.message || String(err) }));
    process.exit(1);
  });
}
